// Load conversation history and build LLM context with lightweight memory
const update = $input.first().json || {};
const telegramMessage = update.message || update.callback_query?.message || {};
const message = String(update.message?.text || update.callback_query?.data || '');
const chatId = update.message?.chat?.id || update.callback_query?.message?.chat?.id || update.callback_query?.from?.id;
const messageId = update.message?.message_id || update.callback_query?.message?.message_id || update.callback_query?.id || null;
const replyToText = String(telegramMessage.reply_to_message?.text || '').trim();
const replyToMessageId = telegramMessage.reply_to_message?.message_id || null;
const repliedByBot = Boolean(telegramMessage.reply_to_message?.from?.is_bot);
const isSlash = message.trim().startsWith('/');

// If this is a callback query, keep the original message text for fallback parsing
const sourceMessageText = String(update.callback_query?.message?.text || '').trim();
const sourceMessageId = update.callback_query?.message?.message_id || null;
const callbackQueryId = update.callback_query?.id || null;

const staticData = $getWorkflowStaticData('global');
if (chatId) staticData.defaultChatId = String(chatId);
if (!staticData.conversations) staticData.conversations = {};
if (!staticData.userMemory) staticData.userMemory = {};

const chatKey = String(chatId || '');
const now = Date.now();
const TWO_HOURS = 2 * 60 * 60 * 1000;

if (staticData.conversations[chatKey] && (now - staticData.conversations[chatKey].lastActivity) > TWO_HOURS) {
  delete staticData.conversations[chatKey];
}

if (!staticData.conversations[chatKey]) {
  staticData.conversations[chatKey] = { messages: [], lastActivity: now };
}

const conv = staticData.conversations[chatKey];
conv.lastActivity = now;

if (message) {
  conv.messages.push({ role: 'user', content: message });
}

if (conv.messages.length > 12) {
  conv.messages = conv.messages.slice(-12);
}

const pending = staticData.pendingContent?.[chatKey] || null;
const mem = staticData.userMemory[chatKey] || {};

const memorySummary = [
  pending ? `pending_type=${pending.type || 'unknown'}` : 'pending_type=none',
  pending ? `pending_title="${(pending.title || pending.args || 'untitled').replace(/"/g, "'")}"` : 'pending_title=none',
  mem.lastAction ? `last_action=${mem.lastAction}` : 'last_action=none',
  mem.lastTopic ? `last_topic="${String(mem.lastTopic).replace(/"/g, "'")}"` : 'last_topic=none'
].join('; ');

const systemPrompt = `You are Dignitate's assistant in Telegram. Dignitate is a UK charity supporting cultural carers in the dementia journey.

Behave like a natural LLM chat assistant: warm, practical, concise, and context-aware.
- Default to natural conversation, not command-style instructions.
- Do not mention slash commands unless the user explicitly asks.
- Keep most replies to 1-3 short sentences.
- Ask at most one clarifying question only when essential.
- If user confirms (for example: yes, do it, go ahead, make it), use prior context and proceed.

CAPABILITIES:
- Create Instagram carousel drafts with generated images
- Create short-form video drafts
- Pull latest dementia-care trends
- Approve/regenerate pending drafts for posting
- View post performance stats with /stats

ALWAYS return valid JSON only, no markdown, no extra text:
{"reply":"assistant reply","action":{"type":"carousel|video|both|trends|approve|regenerate|status|help|stats|none","topic":"topic or empty"}}

ACTION POLICY:
- If user clearly asks for a carousel, set type=carousel.
- If user clearly asks for a video/reel/tiktok, set type=video.
- If user asks for both formats, set type=both.
- If user asks for trends or what to post now, set type=trends.
- If user asks to post/approve/publish, set type=approve.
- If user asks to redo/regenerate/try again, set type=regenerate.
- If user asks for status/help, set type=status/help.
- If user asks for stats or performance data, set type=stats.
- If it is normal chat without execution request, set type=none.
- When action is carousel/video/both and topic is implied by context, infer topic from context.`;

const memoryMessage = `Conversation memory: ${memorySummary}`;

const aiMessages = [
  { role: 'system', content: systemPrompt },
  { role: 'system', content: memoryMessage },
  ...conv.messages
];

const aiMessagesJson = JSON.stringify(aiMessages);

return [{
  json: {
    message,
    chatId,
    messageId,
    replyToText,
    replyToMessageId,
    repliedByBot,
    isSlash,
    sourceMessageText,
    sourceMessageId,
    callbackQueryId,
    conversationHistory: conv.messages,
    aiMessagesJson,
    memorySummary
  }
}];

const input = $input.first().json || {};

function clean(value) {
  return String(value || '').replace(/[\r\n\t]+/g, ' ').replace(/\s+/g, ' ').trim();
}

const researchFacts = Array.isArray(input.researchFacts) ? input.researchFacts : [];
const researchActions = Array.isArray(input.researchActions) ? input.researchActions : [];
const flow = input.narrativeFlow || {};

const body = {
  model: 'openai/gpt-4o-mini',
  temperature: 0.45,
  response_format: { type: 'json_object' },
  messages: [
    {
      role: 'system',
      content: 'You create high-performing 5-slide Instagram carousels for Dignitate, a UK dementia-care support organisation. Return strict JSON only. Use only the supplied research facts and actions. Do not invent numbers, dates, percentages, named bodies, or claims not supported by the provided inputs. Every slide must be complete, useful, and specific. Slide 1 must stop the scroll. Slide 5 must feel like a clean ending with a realistic next step.'
    },
    {
      role: 'user',
      content:
        'TOPIC: ' + clean(input.args || 'dementia caregiving support in the UK') +
        '\n\nARTICLE ANCHOR:' +
        '\n' + JSON.stringify({
          summary: clean(input.selectedTrendSummary || ''),
          source_name: clean(input.selectedTrendSourceName || ''),
          source_url: clean(input.selectedTrendSourceUrl || ''),
          published_at: clean(input.selectedTrendPublishedAt || ''),
        }, null, 2) +
        '\n\nRESEARCH SUMMARY:' + '\n' + clean(input.researchSummary || '') +
        '\n\nRESEARCH FACTS:' + '\n' + JSON.stringify(researchFacts, null, 2) +
        '\n\nPRACTICAL ACTIONS:' + '\n' + JSON.stringify(researchActions, null, 2) +
        '\n\nNARRATIVE FLOW:' + '\n' + JSON.stringify(flow, null, 2) +
        '\n\nReturn JSON with this exact schema:' +
        '\n{' +
        '"title":"string",' +
        '"slides":[{"role":"cover|information|information|action|conclusion","heading":"string","subline":"string","text":"string","imagePrompt":"string"}],'+
        '"caption":"string",'+
        '"hashtags":["string"]'+
        '}' +
        '\n\nRules:' +
        '\n- Exactly 5 slides.' +
        '\n- Heading: 3 to 6 words, no colon, no ellipsis, no generic labels.' +
        '\n- Subline: 16 to 22 words, fully complete, no dangling endings, no filler.' +
        '\n- Slide 1: urgent hook for carers grounded in the article anchor.' +
        '\n- Slide 2: one concrete fact from RESEARCH FACTS.' +
        '\n- Slide 3: what that fact changes in daily care, using another concrete detail from RESEARCH FACTS.' +
        '\n- Slide 4: one practical action from PRACTICAL ACTIONS.' +
        '\n- Slide 5: reassuring close with one realistic next step.' +
        '\n- Do not invent statistics or claims that are not explicitly present in the supplied inputs.' +
        '\n- Avoid phrases like One Key UK Fact, What This Means Daily, Do This Today, Stay, Next Step.' +
        '\n- imagePrompt should describe only the background visual, not overlaid text or branding.' +
        '\n- Hashtags: 5 to 8, relevant to UK dementia care.'
    }
  ]
};

let parsed;
try {
  parsed = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://openrouter.ai/api/v1/chat/completions',
    headers: {
      Authorization: 'Bearer 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',
      'Content-Type': 'application/json',
    },
    body,
    json: true,
  });
} catch (error) {
  const status = error?.response?.statusCode || error?.statusCode || '';
  const bodyText = typeof error?.response?.body === 'string' ? error.response.body : JSON.stringify(error?.response?.body || {});
  throw new Error(String(status || 'request_failed') + ' - ' + bodyText);
}

return [{ json: parsed, pairedItem: { item: 0 } }];

