const content = Array.isArray(rawContent)
  ? rawContent.map((c) => (typeof c === 'string' ? c : (c?.text || JSON.stringify(c)))).join('\n')
  : String(rawContent || '[]');

function clean(s) {
  return String(s || '').replace(/[\r\n]+/g, ' ').replace(/\s+/g, ' ').trim();
}

function asArray(v) {
  if (Array.isArray(v)) return v;
  if (v && typeof v === 'object') {
    for (const key of ['topics', 'trends', 'items', 'results', 'data']) {
      if (Array.isArray(v[key])) return v[key];
    }
    if (v.title || v.topic) return [v];
  }
  return [];
}

function parseJsonLoose(text) {
  const t = String(text || '').trim();
  if (!t) return [];

  const stripped = t
    .replace(/^\x60\x60\x60json\s*/i, '')
    .replace(/^\x60\x60\x60\s*/i, '')
    .replace(/\x60\x60\x60$/i, '')
    .trim();

  try {
    const parsed = JSON.parse(stripped);
    const arr = asArray(parsed);
    if (arr.length) return arr;
  } catch (e) {}

  const aStart = stripped.indexOf('[');
  const aEnd = stripped.lastIndexOf(']');
  if (aStart >= 0 && aEnd > aStart) {
    try {
      const parsed = JSON.parse(stripped.slice(aStart, aEnd + 1));
      const arr = asArray(parsed);
      if (arr.length) return arr;
    } catch (e) {}
  }

  const oStart = stripped.indexOf('{');
  const oEnd = stripped.lastIndexOf('}');
  if (oStart >= 0 && oEnd > oStart) {
    try {
      const parsed = JSON.parse(stripped.slice(oStart, oEnd + 1));
      const arr = asArray(parsed);
      if (arr.length) return arr;
    } catch (e) {}
  }

  return [];
}

function normTitle(s) {
  return clean(s).toLowerCase().replace(/[^a-z0-9\s]/g, '').replace(/\s+/g, ' ').trim();
}

const allowedCategories = new Set(['policy', 'research', 'caregiving', 'community', 'technology', 'finance', 'legal', 'clinical']);
const parsed = parseJsonLoose(content);

let topics = parsed
  .map((t) => {
    const title = clean(t?.title || t?.topic || '');
    const summary = clean(t?.summary || t?.description || '');
    let engagement_score = Number(t?.engagement_score ?? t?.engagementScore ?? 7);
    if (!Number.isFinite(engagement_score)) engagement_score = 7;
    engagement_score = Math.max(1, Math.min(10, Math.round(engagement_score)));

    const rawCat = clean(t?.category || '').toLowerCase();
    const category = allowedCategories.has(rawCat) ? rawCat : 'caregiving';
    const region = clean(t?.region || 'UK');
    const source_url = clean(t?.source_url || t?.sourceUrl || t?.url || '');
    const source_name = clean(t?.source_name || t?.sourceName || t?.source || '');
    const published_at = clean(t?.published_at || t?.publishedAt || t?.date || '');

    return { title, summary, engagement_score, category, region, source_url, source_name, published_at };
