}

const staticData = $getWorkflowStaticData('global');
if (!staticData.sentTrends) staticData.sentTrends = [];
if (!staticData.lastTrendByChat) staticData.lastTrendByChat = {};
if (!staticData.latestSuggestedTopicByChat) staticData.latestSuggestedTopicByChat = {};
if (!staticData.pendingTrendTopicByChat) staticData.pendingTrendTopicByChat = {};
if (!staticData.globalSuggestedTopic) staticData.globalSuggestedTopic = '';
if (!staticData.userMemory) staticData.userMemory = {};
if (!staticData.trendCursorByChat) staticData.trendCursorByChat = {};
if (!staticData.trendHistoryByChat) staticData.trendHistoryByChat = {};
if (!staticData.trendMetaByTitle) staticData.trendMetaByTitle = {};

let chatId = clean(response.chatId || response.chat_id || '');
if (!chatId) {
  try { chatId = clean($('Quick Parse Slash').first().json.chatId); } catch (e) {}
}
if (!chatId) {
  try { chatId = clean($('Load Chat History').first().json.chatId); } catch (e) {}
}
if (!chatId) chatId = clean(staticData.defaultChatId || '');
if (!chatId) return [];

const chatKey = String(chatId);
const now = Date.now();
const dedupeWindowMs = 72 * 60 * 60 * 1000;
staticData.sentTrends = staticData.sentTrends.filter((t) => now - Number(t.timestamp || 0) < dedupeWindowMs);

const historyWindowMs = 24 * 60 * 60 * 1000;
const history = Array.isArray(staticData.trendHistoryByChat[chatKey]) ? staticData.trendHistoryByChat[chatKey] : [];
const recentHistory = history.filter((h) => now - Number(h.timestamp || 0) < historyWindowMs);
staticData.trendHistoryByChat[chatKey] = recentHistory;

const recentlySentGlobal = new Set(staticData.sentTrends.map((t) => normTitle(t.title || '')));
const recentlySentChat = new Set(recentHistory.map((t) => normTitle(t.title || '')));

let fresh = topics.filter((t) => !recentlySentGlobal.has(normTitle(t.title)) && !recentlySentChat.has(normTitle(t.title)));
if (!fresh.length) fresh = topics.filter((t) => !recentlySentChat.has(normTitle(t.title)));
const pool = fresh.length ? fresh : topics;

const sorted = [...pool].sort((a, b) => b.engagement_score - a.engagement_score);
const selected = [];
const usedCat = new Set();

for (const t of sorted) {
  if (!usedCat.has(t.category)) {
    selected.push(t);
    usedCat.add(t.category);
  }
  if (selected.length >= 8) break;
}
for (const t of sorted) {
  if (selected.length >= 8) break;
  if (!selected.includes(t)) selected.push(t);
}

let ordered = selected.slice(0, 8);
const cursor = Number(staticData.trendCursorByChat[chatKey] || 0);
if (ordered.length > 1) {
  const shift = ((cursor % ordered.length) + ordered.length) % ordered.length;
  ordered = ordered.slice(shift).concat(ordered.slice(0, shift));
}
staticData.trendCursorByChat[chatKey] = cursor + 1;

const lastTopNorm = normTitle(staticData.lastTrendByChat[chatKey] || '');
if (ordered.length > 1 && normTitle(ordered[0]?.title || '') === lastTopNorm) {
  const swapIdx = ordered.findIndex((t, i) => i > 0 && normTitle(t.title) !== lastTopNorm);
  if (swapIdx > 0) {
    const tmp = ordered[0];
    ordered[0] = ordered[swapIdx];
    ordered[swapIdx] = tmp;
  }
}

const finalTopics = ordered.slice(0, 8);
for (const t of finalTopics) {
  staticData.sentTrends.push({ title: t.title, category: t.category, timestamp: now });
  const meta = {
    title: t.title,
    summary: t.summary || '',
    category: t.category || '',
    region: t.region || 'UK',
    sourceUrl: t.source_url || '',
    sourceName: t.source_name || '',
    publishedAt: t.published_at || '',
    updatedAt: now
  };
  const keyLower = String(t.title || '').toLowerCase();
  const keyNorm = normTitle(t.title || '');
  if (keyLower) staticData.trendMetaByTitle[keyLower] = meta;
  if (keyNorm) staticData.trendMetaByTitle[keyNorm] = meta;
}

if (finalTopics[0]?.title) {
  const selectedTitle = String(finalTopics[0].title).trim();
  staticData.lastTrendByChat[chatKey] = selectedTitle;
  staticData.latestSuggestedTopicByChat[chatKey] = selectedTitle;
  staticData.pendingTrendTopicByChat[chatKey] = selectedTitle;
  staticData.globalSuggestedTopic = selectedTitle;
  staticData.userMemory[chatKey] = {
    ...(staticData.userMemory[chatKey] || {}),
    lastTopic: selectedTitle,
    lastAction: 'trends',
    updatedAt: now
  };
}

staticData.trendHistoryByChat[chatKey] = [
  ...recentHistory,
  ...finalTopics.map((t) => ({ title: t.title, timestamp: now }))
].slice(-60);

return finalTopics.map((t, idx) => ({
  json: {
    ...t,
    chatId,
    rank: idx + 1,
    totalTopics: finalTopics.length
  }
}));

