let data = input;

// Fallback in case upstream node accidentally passes Telegram API response.
if (!Array.isArray(data.slides) || data.slides.length === 0) {
  try { data = $('Parse Carousel Response').first().json || data; } catch (e) {}
}

if (data.researchBlocked) {
  throw new Error(String(data.researchBlockReason || 'Research quality is too low for reliable carousel generation. Please refine the topic.'));
}

if (data.qualityGate && data.qualityGate.approved === false) {
  const issues = Array.isArray(data.qualityGate.issues) ? data.qualityGate.issues : [];
  const summary = issues.slice(0, 3).map((x) => `[slide ${x.slide || '?'}] ${x.type || 'issue'}`).join(', ');
  throw new Error('Carousel quality gate blocked before image generation: ' + (summary || 'unsupported claims or logo risk'));
}

const slides = Array.isArray(data.slides) ? data.slides : [];
if (!slides.length) {
  throw new Error('No slides found in carousel payload. Ensure Split Slides receives Parse Carousel Response output.');
}

function clean(s) {
  return String(s || '').replace(/[\r\n\t]+/g, ' ').replace(/\s+/g, ' ').trim();
}

return slides.map((slide, idx) => {
  const heading = clean(slide.heading || '');
  const body = clean(slide.subline || slide.body || '');
  const text = clean(slide.text || slide.caption || '');

  return {
    json: {
      slideIndex: idx,
      totalSlides: slides.length,
      slideRole: String(slide.role || (idx === 0 ? 'cover' : (idx === slides.length - 1 ? 'conclusion' : 'information'))),
      imagePrompt: slide.imagePrompt || slide.image_prompt || slide.visualPrompt || slide.prompt || '',
      slideText: text,
      slideHeading: heading,
      slideBody: body,
      chatId: data.chatId,
