parameters.jsCode:
const items = $input.all();
let carouselData = {};
try { carouselData = $('Parse Carousel Response').first().json || {}; } catch (e) {}

const allImageUrls = [];
const expectedCandidates = [];
const failedRequests = [];
const renderRows = [];

function clean(s) {
  return String(s || '').replace(/[\r\n\t]+/g, ' ').replace(/\s+/g, ' ').trim();
}

function classifyTopicKind(topic) {
  const t = clean(topic).toLowerCase();
  if (!t) return 'practical';
  if (/\b(conference|summit|event|meeting|forum|congress|workshop|webinar|symposium|awards?|expo)\b/.test(t)) return 'event';
  if (/\b(research|study|trial|paper|journal|scientist|oligodendrocyte|biomarker|genetic|cell|cells|neuro|prevention\s+strateg(?:y|ies))\b/.test(t)) return 'research';
  if (/\b(framework|standard|standards|guidance|policy|government|minister|nhs\s+england|commission|rollout|strategy|plan|icb|integrated\s+care\s+board|report)\b/.test(t)) return 'policy';
  return 'practical';
}

function isLikelyImageUrl(u, keyPath) {
  const s = String(u || '').trim();
  if (!/^https?:\/\//i.test(s)) return false;

  // Exclude fal queue/status/request endpoints (not assets)
  if (/queue\.fal\.run\/.*\/requests\//i.test(s)) return false;
  if (/api\.fal\.ai\/.*\/requests\//i.test(s)) return false;
  if (/\/status(?:\?|$)/i.test(s) && /fal/i.test(s)) return false;

  const p = String(keyPath || '').toLowerCase();
  if (/image|images|thumbnail|asset|output/.test(p)) return true;
  if (/\.(png|jpe?g|webp|gif)(?:\?|#|$)/i.test(s)) return true;
  if (/fal\.(media|run)|cdn|cloudfront|storage|blob/i.test(s)) return true;
  return false;
}

function collectUrls(node, out, keyPath = '', depth = 0) {
  if (!node || depth > 8) return;
  if (Array.isArray(node)) {
    for (let i = 0; i < node.length; i++) collectUrls(node[i], out, keyPath + '[' + i + ']', depth + 1);
    return;
  }
  if (typeof node === 'string') {
    const u = node.trim();
    if (isLikelyImageUrl(u, keyPath)) out.push(u);
    return;
  }
  if (typeof node !== 'object') return;

  for (const [k, v] of Object.entries(node)) {
    const kp = keyPath ? (keyPath + '.' + k) : k;
    if (typeof v === 'string') {
      if (isLikelyImageUrl(v, kp)) out.push(String(v).trim());
    } else {
      collectUrls(v, out, kp, depth + 1);
    }
  }
}

function collectRow(node) {
  const j = node?.json || node || {};
  if (!j || typeof j !== 'object') return;
  const idx = Number(j.slideIndex);
  const role = clean(j.slideRole || '');
  const heading = clean(j.slideHeading || j.heading || '');
  const body = clean(j.slideBody || j.subline || '');
  const imagePrompt = clean(j.imagePrompt || j.image_prompt || j.visualPrompt || j.prompt || '');
  const falPromptPreview = clean(j.falPromptPreview || '');
  if (Number.isFinite(idx) || role || heading || body || imagePrompt || falPromptPreview) {
    renderRows.push({
      slideIndex: Number.isFinite(idx) ? idx : null,
      slideRole: role,
      slideHeading: heading,
      slideBody: body,
      imagePrompt,
      falPromptPreview,
    });
  }
}

for (const item of items) {
  const j = item?.json || {};

  if (j.falError) {
    failedRequests.push({ request_id: j.request_id || j.requestId || '', error: String(j.falError) });
  }

  collectUrls(j, allImageUrls);
  collectRow(j);

  if (Number.isFinite(Number(j.totalSlides)) && Number(j.totalSlides) > 0) {
    expectedCandidates.push(Number(j.totalSlides));
  }

  const nestedData = Array.isArray(j.data) ? j.data : [];
  for (const row of nestedData) {
    const rowJson = row?.json || row || {};
    collectUrls(rowJson, allImageUrls);
    collectRow(rowJson);

    if (Number.isFinite(Number(rowJson.totalSlides)) && Number(rowJson.totalSlides) > 0) {
      expectedCandidates.push(Number(rowJson.totalSlides));
    }
  }
}

const uniqueUrls = [...new Set(allImageUrls)];
let expectedSlides = Array.isArray(carouselData.slides) ? carouselData.slides.length : 0;
if (!expectedSlides && expectedCandidates.length) {
  expectedSlides = Math.max(...expectedCandidates);
}
if (!expectedSlides) expectedSlides = 5;

if (!uniqueUrls.length) {
  const reason = failedRequests.length
    ? (' fal.ai details: ' + failedRequests.map((f) => (f.request_id ? '[' + f.request_id + '] ' : '') + f.error).join(' | ').slice(0, 700))
    : '';
  const payloadHints = items.slice(0, 2).map((it, idx) => {
    const j = it?.json || {};
    const keys = Object.keys(j).slice(0, 20).join(',');
    const nested = Array.isArray(j.data) ? (' data[' + j.data.length + ']') : '';
    return 'item' + idx + ' keys=' + keys + nested;
  }).join(' | ');
  throw new Error('No image URLs were returned from fal.ai. ' + payloadHints + reason);
}

const partialGeneration = uniqueUrls.length < expectedSlides;
const missingSlides = partialGeneration ? Math.max(0, expectedSlides - uniqueUrls.length) : 0;

// Hard pre-approval QA gate (cheap, metadata-based). Prevents obviously bad carousels before Telegram approval.
const qaIssues = [];
const slides = Array.isArray(carouselData.slides) ? carouselData.slides : [];
const topic = clean(carouselData.args || carouselData.title || '');
const topicKind = classifyTopicKind(topic);
const normalizedRows = [...renderRows].sort((a, b) => (a.slideIndex ?? 999) - (b.slideIndex ?? 999));

function addIssue(type, slide, detail, severity = 'block') {
  qaIssues.push({ type, slide, detail, severity });
}

function textHasLabelLeak(s) {
  const t = clean(s);
  return /(^|\s)(headline|subline)\s*:/i.test(t);
}

function textHasBrokenFragment(s) {
  const t = clean(s);
  return /\bsupport\.\s*for\.?$/i.test(t) || /\bfor\.?$/i.test(t);
}

function textHasRepeatCTA(s) {
  const t = clean(s).toLowerCase();
  return (t.match(/follow dignitate/g) || []).length > 1 || (t.match(/you are not alone/g) || []).length > 1;
}

function promptPosterRisk(s) {
  const t = clean(s).toLowerCase();
  return /\bposter|signage|sign\s*board|waiting\s+room|wall\s+poster\b/.test(t);
}

function isTooGenericHeading(s) {
  const t = clean(s).toLowerCase();
  return ['dementia care update', 'new dementia care update', 'your next step', 'what this means daily', 'one key uk fact', 'do this today'].includes(t);
}

function isEventVisualMismatch(prompt, slideIndex) {
  const t = clean(prompt).toLowerCase();
  if (!t) return true;
  const hasEventCue = /\b(conference|venue|registration|attendees?|session|webinar|organiser|meeting|auditorium|save date|register)\b/.test(t);
  const hasGenericClinicCue = /\b(gp\s+surgery|waiting\s+room|poster|clinic\s+wall)\b/.test(t);
  if (slideIndex <= 3 && !hasEventCue) return true;
  if (slideIndex <= 3 && hasGenericClinicCue) return true;
  return false;
}

for (let i = 0; i < slides.length; i++) {
  const s = slides[i] || {};
  const heading = clean(s.heading || '');
  const subline = clean(s.subline || '');
  const text = clean((s.text || '') + ' ' + heading + ' ' + subline);
  const prompt = clean(s.imagePrompt || '');
  const row = normalizedRows.find((r) => r.slideIndex === i) || {};
  const falPreview = clean(row.falPromptPreview || '');

  if (textHasLabelLeak(text) || textHasLabelLeak(falPreview)) {
    addIssue('label_leak', i + 1, 'Detected Headline/Subline label leakage in slide text or render prompt');
  }
  if (textHasBrokenFragment(subline)) {
    addIssue('broken_copy', i + 1, 'Detected broken CTA fragment (for./support. for.)');
  }
  if (textHasRepeatCTA(subline) && i === slides.length - 1) {
    addIssue('repeated_cta', i + 1, 'Conclusion copy repeats CTA/reassurance phrase');
  }
  if (promptPosterRisk(prompt)) {
    addIssue('poster_risk', i + 1, 'Scene prompt still includes poster/signage/waiting-room risk terms');
  }
  if (i > 0 && i < slides.length - 1 && isTooGenericHeading(heading)) {
    addIssue('generic_heading', i + 1, 'Information slide heading is still too generic', 'warn');
  }
  if (topicKind === 'event' && isEventVisualMismatch(prompt, i)) {
    addIssue('event_visual_mismatch', i + 1, 'Event topic slide prompt is not venue/session/registration aligned', 'warn');
  }
}

if (partialGeneration) {
  addIssue('partial_generation', null, 'Only ' + uniqueUrls.length + ' of ' + expectedSlides + ' images generated');
}

const blockingQaIssues = qaIssues.filter((x) => x.severity !== 'warn');
if (blockingQaIssues.length) {
  const summary = blockingQaIssues.slice(0, 6).map((x) => {
    const prefix = x.slide ? ('slide ' + x.slide + ': ') : '';
    return prefix + x.type + ' - ' + x.detail;
  }).join(' | ');
  throw new Error('Carousel QA gate blocked approval: ' + summary);
}

return [{ json: {
  ...carouselData,
  backgroundImageUrls: uniqueUrls,
  allImageUrls: uniqueUrls,
  imageUrl: uniqueUrls[0] || '',
  firstImageUrl: uniqueUrls[0] || '',
  imageCount: uniqueUrls.length,
  expectedSlides,
  partialGeneration,
  missingSlides,
  failedRequests,
  renderPending: true,
  qaReview: {
    approved: true,
    topicKind,
    checkedSlides: slides.length,
    renderRowsSeen: normalizedRows.length,
    issues: qaIssues.slice(0, 20),
  },
} }];

const staticData = $getWorkflowStaticData('global');
if (!staticData.pendingContent) staticData.pendingContent = {};
if (!staticData.activeGenerationByChat) staticData.activeGenerationByChat = {};

const data = $input.first().json || {};
const chatId = String(data.chatId || '').trim();
if (!chatId) return [];

const isDraft = data.renderPending === true || String(data.renderPending || '').toLowerCase() === 'true';
const imageUrls = Array.isArray(data.allImageUrls) ? data.allImageUrls.filter(Boolean) : [];
const backgroundImageUrls = Array.isArray(data.backgroundImageUrls)
  ? data.backgroundImageUrls.filter(Boolean)
  : imageUrls;

staticData.pendingContent[chatId] = {
  type: 'carousel',
  title: data.title,
  slides: Array.isArray(data.slides) ? data.slides : [],
  hashtags: Array.isArray(data.hashtags) ? data.hashtags : [],
  caption: String(data.caption || '').trim(),
  backgroundImageUrls,
  allImageUrls: imageUrls,
  imageUrl: data.imageUrl,
  firstImageUrl: data.firstImageUrl,
  imageCount: Number.isFinite(Number(data.imageCount)) ? Number(data.imageCount) : imageUrls.length,
  chatId: data.chatId,
  args: data.args,
  renderStatus: isDraft ? 'rendering' : 'ready',
  renderPending: isDraft,
  timestamp: Date.now()
};

delete staticData.activeGenerationByChat[chatId];

if (isDraft) {
  return [];
}

return [{
  json: {
    ...data,
    renderPending: false,
    allImageUrls: imageUrls,
    backgroundImageUrls,
  }
}];

