const videoData = $('Resolve Founder Portrait URL').first().json || $('Parse Video Response').first().json || {};

function clean(s) {
  return String(s || '').replace(/[\r\n\t]+/g, ' ').replace(/\s+/g, ' ').trim();
}

function uniq(parts) {
  const out = [];
  const seen = new Set();
  for (const p of parts) {
    const t = clean(p);
    if (!t) continue;
    const k = t.toLowerCase();
    if (seen.has(k)) continue;
    seen.add(k);
    out.push(t);
  }
  return out.join(', ');
}

function stripMetaLabels(text) {
  let t = clean(text);
  if (!t) return t;
  t = t
    .replace(/^(why this matters now|what changed|evidence update|what this means for carers|next step|key takeaway)\s*[:\-]\s*/i, '')
    .replace(/\b(key takeaway)\s*[:\-].*$/i, '')
    .trim();
  return t;
}

function intentFromNarration(text) {
  const t = stripMetaLabels(text);
  return t || 'practical UK dementia-care guidance for carers';
}

function visualCore(raw) {
  return clean(String(raw || '').split(/topic context:/i)[0]);
}

function stripIdentityDrift(text) {
  return clean(text)
    .replace(/\bresembling[^,.;]*/ig, '')
    .replace(/\b(?:a|an)?\s*(?:young|middle-aged|elderly)\s+(?:man|woman|person)\b/ig, '')
    .replace(/\b(?:man|woman)\s+with\s+[^,.;]*/ig, '')
    .replace(/\b(?:male|female)\b/ig, '')
    .replace(/\b(?:blonde|red-haired|blue-eyed|green-eyed)\b/ig, '')
    .replace(/\b(?:same man|same woman|different person)\b/ig, '');
}

function hashSeed(str) {
  const s = String(str || '');
  let h = 0;
  for (let i = 0; i < s.length; i++) {
    h = ((h << 5) - h + s.charCodeAt(i)) | 0;
  }
  return Math.abs(h);
}

const scenes = Array.isArray(videoData.allScenes) ? videoData.allScenes : [];

const mode = String(videoData.videoMode || videoData.video_mode || "").toLowerCase().trim();
const isTalkingHead = mode === "talking_head";

const staticData = $getWorkflowStaticData('global');
if (!staticData.videoContinuityByChat) staticData.videoContinuityByChat = {};
const chatKey = String(videoData.chatId || staticData.defaultChatId || '');

const continuityDefaults = {
  identityAnchor: 'same exact founder identity from reference image, match face geometry, skin tone, hairstyle, no identity drift',
  wardrobeAnchor: isTalkingHead ? 'wardrobe: podcast host style, clean modern clothing, subtle variation allowed (different shirt/jacket) but still consistent identity' : 'wardrobe consistent across scenes, professional UK healthcare editorial clothing',
  cameraAnchor: 'vertical 9:16, chest-up framing, eyes sharp, natural skin texture, documentary realism',
  negative: 'no borders, no black bars, no letterboxing, no text, no captions, no logos, no watermark, no UI, no collage, no grid, no split-screen'
};

const continuity = {
  ...continuityDefaults,
  ...(chatKey ? (staticData.videoContinuityByChat[chatKey] || {}) : {})
};
if (chatKey) staticData.videoContinuityByChat[chatKey] = continuity;

const settingByType = isTalkingHead
  ? {
      hook: 'podcast/recording studio setup, visible microphone, warm studio lighting, clean background',
      cta: 'podcast/recording studio setup, visible microphone, warm studio lighting, clean background',
      scene: 'podcast/recording studio setup, visible microphone, warm studio lighting, clean background'
    }
  : {
      hook: 'quiet NHS clinic consult room or community health centre, soft daylight, calm tone',
      scene: 'UK home-care planning moment at a kitchen table, practical props (calendar, leaflet, pill organiser), soft daylight',
      cta: 'warm UK living room or community centre, hopeful closing moment, calm and reassuring'
    };

const motionByType = isTalkingHead
  ? {
      hook: 'locked-off tripod, subtle natural head movement, minimal camera motion',
      scene: 'locked-off tripod, subtle natural head movement, minimal camera motion',
      cta: 'locked-off tripod, subtle natural head movement, minimal camera motion'
    }
  : {
      hook: 'gentle dolly-in, natural pacing',
      scene: 'subtle handheld documentary motion, small natural gestures',
      cta: 'slow cinematic push-in, calm finish'
    };

const shotByIndex = isTalkingHead
  ? [
      'vertical medium shot, presenter at desk with microphone, camera at eye level',
      'vertical medium shot, presenter with microphone, slight angle change'
    ]
  : [
      'vertical medium shot, camera at eye level',
      'vertical close-up, subtle expression detail'
    ];

return scenes.map((scene, idx) => {
  const sceneType = String(scene?.type || (idx === 0 ? 'hook' : (idx === scenes.length - 1 ? 'cta' : 'scene'))).toLowerCase();
  const shot = shotByIndex[idx % shotByIndex.length];
  const motion = motionByType[sceneType] || motionByType.scene;

  const intent = intentFromNarration(scene?.narration || '');
  const visualHint = stripIdentityDrift(visualCore(scene?.visualPrompt || ''));
  const fallbackSetting = settingByType[sceneType] || settingByType.scene;

  const framingLock = 'composition: subject centred, face in upper-middle (upper third), hands visible if possible, leave bottom 30% uncluttered for subtitles';

  const videoPrompt = uniq([
    'Photorealistic UK documentary scene: ' + intent,
    visualHint || fallbackSetting,
    continuity.identityAnchor,
    continuity.wardrobeAnchor,
    continuity.cameraAnchor,
    framingLock,
    motion,
    shot,
    continuity.negative
  ]);

  const sceneImagePrompt = uniq([
    'Create a NEW photorealistic still frame (start image) for a vertical 9:16 short.',
    'Same exact founder identity as reference images (strict).',
    ...(isTalkingHead ? [] : ['Change the environment/background completely (do NOT keep the original portrait/studio background).']),
    'Scene: ' + (visualHint || fallbackSetting) + '. Must match the narration meaning: ' + intent,
    continuity.identityAnchor,
    continuity.wardrobeAnchor,
    continuity.cameraAnchor,
    framingLock,
    'lighting: natural window light, neutral-warm grade, realistic skin texture',
    'no other prominent people, no distorted hands, no extra fingers',
    continuity.negative
  ]);

  const sceneSeed = hashSeed(String(videoData.title || '') + '|' + String(videoData.chatId || '') + '|' + String(idx));

  return {
    json: {
      ...scene,
      sceneIndex: idx,
      totalScenes: scenes.length,
      chatId: videoData.chatId,
      title: videoData.title,
      hashtags: videoData.hashtags,
      caption: videoData.caption,
      fullNarration: videoData.fullNarration,
      creatorImageUrl: videoData.creatorImageUrl || '',
      creatorImageUrls: Array.isArray(videoData.creatorImageUrls) ? videoData.creatorImageUrls : [],
      creatorVoiceId: videoData.creatorVoiceId || 'GoLTMzQJAHarswiHqv3L',
      continuityProfile: continuity,
      videoPrompt,
      sceneImagePrompt,
      sceneSeed,
    }
  };
});

// Package a lightweight video job for GitHub Actions.
// All heavy generation (scene images + Kling clips) is done in GitHub Actions to avoid n8n Cloud timeouts.

const items = $input.all();
const parseVideoData = $('Parse Video Response').first().json || {};
const first = items[0]?.json || {};

const dataArr = Array.isArray(first.data) ? first.data : [];

function clean(s) {
  return String(s ?? '').replace(/\s+/g, ' ').trim();
}

function pick(...vals) {
  for (const v of vals) {
    const t = clean(v);
    if (t) return t;
  }
  return '';
}

function asNumber(v, fallback) {
  const n = Number(v);
  return Number.isFinite(n) && n > 0 ? n : fallback;
}

function isHttpUrl(v) {
  return /^https?:\/\//i.test(String(v || '').trim());
}

function capUrls(list, max = 3) {
  const out = [];
  const seen = new Set();
  for (const raw of (Array.isArray(list) ? list : [])) {
    const u = String(raw || '').trim();
    if (!u || !isHttpUrl(u)) continue;
    const k = u.toLowerCase();
    if (seen.has(k)) continue;
    seen.add(k);
    out.push(u);
    if (out.length >= max) break;
  }
  return out;
}

const mode = String(parseVideoData.videoMode || parseVideoData.video_mode || first.videoMode || "").toLowerCase().trim();
const MAX_SCENES = mode === "talking_head" ? 1 : 2;

// Scenes coming from Prepare Video Scenes contain videoPrompt + sceneImagePrompt.
const sourceScenes = dataArr.length
  ? dataArr
  : (Array.isArray(parseVideoData.allScenes) ? parseVideoData.allScenes : []);

const trimmed = sourceScenes.slice(0, MAX_SCENES);
const total = trimmed.length;

const scenes = trimmed.map((s, idx) => {
  const duration = asNumber(s?.duration, mode === "talking_head" ? 18 : 12);
  const type = pick(s?.type, idx === 0 ? 'hook' : (idx === (total - 1) ? 'cta' : 'scene'));

  return {
    narration: pick(s?.narration, s?.text),
    visualPrompt: pick(s?.visualPrompt, s?.imagePrompt, s?.prompt),
    type,
    duration,
    index: Number.isFinite(Number(s?.index)) ? Number(s.index) : idx,

    // Added by Prepare Video Scenes
    videoPrompt: pick(s?.videoPrompt, s?.visualPrompt),
    sceneImagePrompt: pick(s?.sceneImagePrompt, s?.visualPrompt),

    // Identity anchors (cap to 3 to control cost)
    creatorImageUrl: pick(s?.creatorImageUrl, parseVideoData.creatorImageUrl),
    creatorImageUrls: capUrls(
      Array.isArray(s?.creatorImageUrls)
        ? s.creatorImageUrls
        : (Array.isArray(parseVideoData.creatorImageUrls) ? parseVideoData.creatorImageUrls : []),
      3
    ),
  };
});

const title = pick(parseVideoData.title, first.title, 'Untitled Video');
const chatId = pick(parseVideoData.chatId, first.chatId);
const args = pick(parseVideoData.args, first.args);
const hashtags = Array.isArray(parseVideoData.hashtags)
  ? parseVideoData.hashtags
  : (Array.isArray(first.hashtags) ? first.hashtags : []);
const caption = pick(parseVideoData.caption, first.caption);

const fullNarration = pick(
  parseVideoData.fullNarration,
  first.fullNarration,
  scenes.map((s) => clean(s.narration)).filter(Boolean).join(' ')
);

const creatorVoiceId = pick(parseVideoData.creatorVoiceId, first.creatorVoiceId, 'GoLTMzQJAHarswiHqv3L');

const creatorImageUrl = pick(
  scenes[0]?.creatorImageUrl,
  parseVideoData.creatorImageUrl,
  first.creatorImageUrl
);

const creatorImageUrls = capUrls(
  (Array.isArray(scenes[0]?.creatorImageUrls) && scenes[0].creatorImageUrls.length)
    ? scenes[0].creatorImageUrls
    : (Array.isArray(parseVideoData.creatorImageUrls) ? parseVideoData.creatorImageUrls : []),
  3
);

const out = {
  type: 'video',
  title,
  hashtags,
  caption,
  chatId,
  args,
  videoMode: mode || "kling_multiclip",
  targetAspectRatio: '9:16',
  targetWidth: 1080,
  targetHeight: 1920,

  // Clip generation is handled in GitHub Actions; these are optional.
  clipUrls: [],
  clipRequests: [],
  clipCount: scenes.length,

  scenes,
  fullNarration,
  narrationText: fullNarration,
  creatorVoiceId,
  creatorImageUrl,
  creatorImageUrls,

  status: 'queued'
};

// Clear active-generation lock for this chat (best-effort)
try {
  const chatKey = String(chatId || '');
  const staticData = $getWorkflowStaticData('global');
  if (staticData?.activeGenerationByChat && chatKey) delete staticData.activeGenerationByChat[chatKey];
} catch (e) {}

return [{ json: out }];

// Prepare payload for GitHub rendering.
// Renderer can synthesize audio from narrationText + voiceId if audioUrl is empty.
const data = $input.first().json || {};
const staticData = $getWorkflowStaticData('global');
if (!staticData.pendingContent) staticData.pendingContent = {};
const mode = String(data.videoMode || '').trim().toLowerCase();
let sourceVideoUrl = String(data.sourceVideoUrl || data.source_video_url || '').trim();
let meetingConfig = (data.meetingConfig && typeof data.meetingConfig === 'object') ? data.meetingConfig : {};
let title = String(data.title || '').trim();
if (mode === 'meeting_reels') {
  const chatKey = String(data.chatId || '');
  const pending = (chatKey && staticData.pendingContent?.[chatKey] && typeof staticData.pendingContent[chatKey] === 'object')
    ? staticData.pendingContent[chatKey]
    : {};
  if (!sourceVideoUrl) sourceVideoUrl = String(data.args || '').trim();
  if (!sourceVideoUrl) sourceVideoUrl = String(pending.sourceVideoUrl || '').trim();
  if (!Object.keys(meetingConfig).length && pending.meetingConfig && typeof pending.meetingConfig === 'object') {
    meetingConfig = pending.meetingConfig;
  }
  title = String(pending.title || title || 'Meeting Reels').trim();
}


let hasVoiceoverBinary = false;
try {
  const audioBinary = $('ElevenLabs - Create Voiceover').first().binary;
  hasVoiceoverBinary = Boolean(audioBinary?.audioFile?.data);
} catch (e) {
  hasVoiceoverBinary = false;
}

return [{
  json: {
    ...data,
    title: title || String(data.title || '').trim(),
    sourceVideoUrl,
    meetingConfig,
    audioUrl: String(data.audioUrl || '').trim(),
    narrationText: String(data.narrationText || data.fullNarration || '').trim(),
    creatorVoiceId: String(data.creatorVoiceId || 'GoLTMzQJAHarswiHqv3L').trim(),
    hasVoiceoverBinary
  }
}];

