const staticData = $getWorkflowStaticData('global');
if (!staticData.pendingContent) staticData.pendingContent = {};
if (!Array.isArray(staticData.approvedArchiveQueue)) staticData.approvedArchiveQueue = [];

const commandData = $('Load Chat History').first().json || {};
const chatId = String(commandData.chatId || $json.chatId || '').trim();

function clean(s) {
  return String(s || '').replace(/[\r\n]+/g, ' ').replace(/\s+/g, ' ').trim();
}

function uniqHashtags(list) {
  const out = [];
  const seen = new Set();
  for (const raw of (Array.isArray(list) ? list : [])) {
    let h = clean(raw);
    if (!h) continue;
    if (!h.startsWith('#')) h = '#' + h;
    const key = h.toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    out.push(h);
  }
  return out;
}

const rawCommand = [
  commandData.message,
  commandData.callbackQueryData,
  commandData.callback_data,
  commandData.sourceMessageText,
  commandData.replyToText,
  commandData.command,
  $json.message,
  $json.callbackQueryData,
  $json.callback_data,
].map(clean).find(Boolean) || '';

const approvalMatch = rawCommand.match(/\/approve(?:@[A-Za-z0-9_]+)?(?:\s+([^\s]+))?/i);
const requestedApprovalId = clean(
  approvalMatch?.[1] ||
  commandData.args ||
  $json.args ||
  $json.approvalId ||
  ''
);

const pending = chatId ? staticData.pendingContent[chatId] : null;

// Expire pending content after 72 hours
const _APPROVAL_TTL = 72 * 60 * 60 * 1000;
if (pending && (Date.now() - (pending.timestamp || 0)) > _APPROVAL_TTL) {
  delete staticData.pendingContent[chatId];
  return [{ json: { chatId, error: true, message: 'Content expired (72h limit). Generate new content with /carousel, /video, or /meeting.' } }];
}

if (!pending) {
  return [{ json: { chatId, error: true, message: 'No pending content found. Generate content first with /carousel, /video, or /meeting.' } }];
}

const approvalItems = Array.isArray(pending.approvalItems) ? pending.approvalItems : [];
if (approvalItems.length) {
  const selected = requestedApprovalId
    ? approvalItems.find((item) => String(item?.approvalId || '').trim() === requestedApprovalId)
    : approvalItems[0];

  if (!selected) {
    return [{ json: { chatId, error: true, message: 'Could not find that meeting reel approval item. Please approve from the latest buttons.' } }];
  }

  const remaining = approvalItems.filter((item) => String(item?.approvalId || '').trim() !== String(selected.approvalId || '').trim());
  if (remaining.length) {
    staticData.pendingContent[chatId] = {
      ...pending,
      approvalItems: remaining,
      lastApprovedId: selected.approvalId,
      timestamp: Date.now(),
    };
  } else {
    delete staticData.pendingContent[chatId];
  }

  const approvedAt = new Date().toISOString();
  const approvedVideoUrl = clean(selected.finalVideoUrl || selected.videoUrl || '');
  const archiveId = clean(selected.archiveId || selected.approvalId || `${chatId}-${Date.now()}`);

  if (approvedVideoUrl && !staticData.approvedArchiveQueue.some((item) => String(item?.archiveId || '') === archiveId)) {
    staticData.approvedArchiveQueue.push({
      archiveId,
      title: clean(selected.title || pending.title || 'Approved Clip'),
      parentTitle: clean(selected.parentTitle || pending.title || ''),
      videoUrl: approvedVideoUrl,
      caption: clean(selected.caption || pending.caption || ''),
      description: clean(selected.description || ''),
      hashtags: uniqHashtags(selected.hashtags || pending.hashtags || []),
      assetType: 'video',
      chatId,
      sourceArgs: clean(selected.args || pending.args || ''),
      approvedAt,
      archivedAt: '',
      archiveTag: '',
      archiveReleaseUrl: '',
      archiveAssetUrl: '',
      archiveMetadataUrl: '',
    });
  }

  return [{
    json: {
      ...selected,
      type: 'video',
      assetType: 'video',
      chatId,
      approved: true,
      finalVideoUrl: approvedVideoUrl,
      videoUrl: approvedVideoUrl,
      caption: clean(selected.caption || pending.caption || ''),
      hashtags: uniqHashtags(selected.hashtags || pending.hashtags || []),
      parentTitle: clean(selected.parentTitle || pending.title || ''),
      args: clean(selected.args || pending.args || ''),
      sourceVideoUrl: clean(selected.sourceVideoUrl || pending.sourceVideoUrl || pending.args || ''),
      meetingConfig: (selected.meetingConfig && typeof selected.meetingConfig === 'object')
        ? selected.meetingConfig
        : ((pending.meetingConfig && typeof pending.meetingConfig === 'object') ? pending.meetingConfig : {}),
      archiveId,
      approvedAt,
    }
  }];
}

const contentData = { ...pending };
delete staticData.pendingContent[chatId];

const approvedVideoUrl = clean(contentData.finalVideoUrl || contentData.videoUrl || '');
const archiveId = clean(contentData.archiveId || `${chatId}-${Date.now()}`);
if (approvedVideoUrl && !staticData.approvedArchiveQueue.some((item) => String(item?.archiveId || '') === archiveId)) {
  staticData.approvedArchiveQueue.push({
    archiveId,
    title: clean(contentData.title || 'Approved Clip'),
    parentTitle: clean(contentData.parentTitle || ''),
    videoUrl: approvedVideoUrl,
    caption: clean(contentData.caption || ''),
    description: clean(contentData.description || ''),
    hashtags: uniqHashtags(contentData.hashtags || []),
    assetType: clean(contentData.assetType || contentData.type || 'video'),
    chatId,
    sourceArgs: clean(contentData.args || ''),
    approvedAt: new Date().toISOString(),
    archivedAt: '',
    archiveTag: '',
    archiveReleaseUrl: '',
    archiveAssetUrl: '',
    archiveMetadataUrl: '',
  });
}

return [{
  json: {
    ...contentData,
    chatId,
    approved: true,
    archiveId,
  }
}];

const staticData = $getWorkflowStaticData('global');
if (!staticData.pendingContent) staticData.pendingContent = {};

const commandData = $('Load Chat History').first().json;
const chatId = String(commandData.chatId);
const pending = staticData.pendingContent[chatId];

if (!pending) {
  return [{ json: { chatId: commandData.chatId, error: true, message: 'No pending content found. Generate content first with /carousel or /video.' } }];
}

const contentData = { ...pending };
delete staticData.pendingContent[chatId];

return [{ json: { ...contentData, chatId: commandData.chatId, regenerate: true } }];

function clean(s) {
  return String(s || '').replace(/[\r\n]+/g, ' ').replace(/\s+/g, ' ').trim();
}

function stripPrefixes(text) {
  return clean(text)
    .replace(/^why this matters now:\s*/i, '')
    .replace(/^what changed:\s*/i, '')
    .replace(/^evidence update:\s*/i, '')
    .replace(/^what this means for carers:\s*/i, '')
    .replace(/^what carers can do next:\s*/i, '')
    .trim();
}

function uniqHashtags(list) {
  const out = [];
  const seen = new Set();
  for (const raw of (Array.isArray(list) ? list : [])) {
    let h = clean(raw);
    if (!h) continue;
    if (!h.startsWith('#')) h = '#' + h;
    const key = h.toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    out.push(h);
  }
  return out;
}

const input = $input.first().json || {};
let data = { ...input };

// After Telegram confirmation nodes, payload can be replaced by Telegram API response.
// Recover canonical approved content from Handle Approval when needed.
const looksLikeTelegramOnly = !data.title && !data.caption && !Array.isArray(data.slides) && !data.imageUrl;
if (looksLikeTelegramOnly) {
  try {
    const approved = $('Handle Approval').first().json || {};
    data = { ...approved };
  } catch (e) {}
}

const title = clean(data.title || data.args || 'Dementia Care Update');
const slides = Array.isArray(data.slides) ? data.slides : [];
const allImageUrls = Array.isArray(data.allImageUrls) ? data.allImageUrls.filter(Boolean) : [];
const imageUrl = clean(data.imageUrl || allImageUrls[0] || '');
const chatId = data.chatId;
const type = clean(data.type || 'carousel').toLowerCase();

let hashtags = uniqHashtags(data.hashtags || []);
if (!hashtags.length) {
  hashtags = ['#DementiaCare', '#CarerSupport', '#UKHealth', '#Dignitate'];
}

let baseCaption = clean(data.caption || '');
if (!baseCaption) {
  baseCaption = 'Evidence-led update for carers with practical next steps and clear takeaways.';
}

const keyPoints = slides
  .map((s) => stripPrefixes(s?.text || s?.caption || ''))
  .filter(Boolean)
  .slice(0, 5);

const pointLines = keyPoints.map((p) => '- ' + p);

const defaultIntro = 'A practical update from Dignitate for carers and families navigating dementia support.';
const intro = baseCaption || defaultIntro;

const instagramCaption = [
  title,
  intro,
  pointLines.length ? 'Key points:\n' + pointLines.join('\n') : '',
  'Save and share with carers who need clear, practical guidance.',
  hashtags.join(' ')
].filter(Boolean).join('\n\n').slice(0, 2100);

const linkedinText = [
  title,
  intro,
  pointLines.length ? 'Highlights:\n' + pointLines.join('\n') : '',
  'Dignitate shares evidence-led dementia content to support cultural carers and families across the UK.',
  hashtags.slice(0, 8).join(' ')
].filter(Boolean).join('\n\n').slice(0, 2900);

const facebookText = [
  title,
  intro,
  pointLines.length ? 'Highlights:\n' + pointLines.join('\n') : '',
  'Follow Dignitate for more practical dementia support.',
  hashtags.slice(0, 8).join(' ')
].filter(Boolean).join('\n\n').slice(0, 4900);

const xCore = [
  title,
  keyPoints[0] ? keyPoints[0] : intro,
  'Practical next steps for carers in the full carousel.'
].filter(Boolean).join(' ');
const xTags = hashtags.slice(0, 3).join(' ');
const xText = (xCore + (xTags ? (' ' + xTags) : '')).slice(0, 275);

const rawFacebookPageId = clean(data.facebookPageId || '672136448');

return [{
  json: {
    chatId,
    type,
    title,
    caption: baseCaption,
    hashtags,
    allImageUrls,
    imageUrl,
    slides,
    instagramCaption,
    linkedinText,
    facebookText,
    facebookPageId: rawFacebookPageId,
    xText
  }
}];

// Store most recent carousel post metadata for /stats
const staticData = $getWorkflowStaticData('global');
if (!staticData.recentPosts) staticData.recentPosts = [];
try {
  const igRaw = $('Composio - Instagram').first().json;
  const igMediaId = igRaw?.data?.id || igRaw?.id || null;
  const postTitle = $('Prepare Post Data').first().json?.title || 'Carousel';
  if (igMediaId) {
    staticData.recentPosts.unshift({
      type: 'carousel', title: postTitle,
      timestamp: Date.now(), igMediaId,
      platforms: ['Instagram', 'LinkedIn', 'Facebook', 'X/Twitter']
    });
    staticData.recentPosts = staticData.recentPosts.slice(0, 10);
  }
} catch(e) {}

const postData = $('Prepare Post Data').first().json;
let igStatus = 'Failed';
let liStatus = 'Failed';
let fbStatus = postData.facebookPageId ? 'Failed' : 'Skipped';
let twStatus = 'Failed';

try {
  const igResult = $('Composio - Instagram').first().json;
  if (igResult && !igResult.error) igStatus = 'Posted';
} catch(e) {}

try {
  const liResult = $('Composio - LinkedIn').first().json;
  if (liResult && !liResult.error) liStatus = 'Posted';
} catch(e) {}

try {
  if (postData.facebookPageId) {
    const fbResult = $('Composio - Facebook').first().json;
    if (fbResult && !fbResult.error && fbResult.successful !== false) fbStatus = 'Posted';
  }
} catch(e) {}

try {
  const twResult = $('Composio - X/Twitter').first().json;
  if (twResult && !twResult.error) twStatus = 'Posted';
} catch(e) {}

const statuses = [igStatus, liStatus, fbStatus, twStatus];
const allSucceeded = statuses.every((s) => s === 'Posted' || s === 'Skipped');
const noneSucceeded = statuses.every((s) => s === 'Failed');

let summary;
if (allSucceeded) {
  summary = 'CAROUSEL POSTED SUCCESSFULLY!\n\nInstagram: ' + igStatus + '\nLinkedIn: ' + liStatus + '\nFacebook: ' + fbStatus + '\nX/Twitter: ' + twStatus + '\n\nLive on all configured platforms!';
} else if (noneSucceeded) {
  summary = 'POSTING FAILED\n\nInstagram: ' + igStatus + '\nLinkedIn: ' + liStatus + '\nFacebook: ' + fbStatus + '\nX/Twitter: ' + twStatus + '\n\nPlease check API credentials and try again.';
} else {
  summary = 'POSTING PARTIALLY COMPLETE\n\nInstagram: ' + igStatus + '\nLinkedIn: ' + liStatus + '\nFacebook: ' + fbStatus + '\nX/Twitter: ' + twStatus + '\n\nSome platforms may need attention.';
}

if (!postData.facebookPageId) {
  summary += '\n\nFacebook is connected but no Facebook Page ID is configured yet.';
}

return [{ json: { chatId: postData.chatId, message: summary } }];

