function normalizeGithubRawUrl(u) {
  const s = clean(u);
  if (!s) return '';

  // Convert GitHub blob URLs into raw.githubusercontent.com URLs.
  // https://github.com/<owner>/<repo>/blob/<branch>/<path>
  const m = s.match(/^https?:\/\/github\.com\/([^\/]+)\/([^\/]+)\/blob\/([^\/]+)\/(.+)$/i);
  if (m) {
    const owner = m[1];
    const repo = m[2];
    const branch = m[3];
    const path = m[4];
    return `https://raw.githubusercontent.com/${owner}/${repo}/${branch}/${path}`;
  }

  return s;
}

function isHttpUrl(v) {
  return /^https?:\/\//i.test(clean(v));
}

function normalizeUrlList(list) {
  if (!Array.isArray(list)) return [];
  const out = [];
  const seen = new Set();
  for (const item of list) {
    const u = normalizeGithubRawUrl(item);
    if (!isHttpUrl(u)) continue;
    const key = u.toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    out.push(u);
  }
  return out;
}

