function shortHash(...parts) {
  const raw = parts.map((p) => String(p || '')).join('|');
  let h = 0;
  for (let i = 0; i < raw.length; i++) {
    h = ((h << 5) - h) + raw.charCodeAt(i);
    h |= 0;
  }
  return Math.abs(h).toString(36);
}

function sentenceSplit(text) {
