const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

function getStatusCode(err) {
  const candidates = [
    err?.statusCode,
    err?.status,
    err?.httpCode,
    err?.response?.statusCode,
    err?.response?.status
  ];
  for (const c of candidates) {
    const n = Number(c);
    if (Number.isFinite(n)) return n;
  }

  const msg = String(err?.message || '');
  const m = msg.match(/status\s*code\s*(\d{3})/i) || msg.match(/\b(\d{3})\b/);
  if (m?.[1]) {
    const n = Number(m[1]);
    if (Number.isFinite(n)) return n;
  }
  return null;
}

function safeJson(v, maxLen = 500) {
  try {
    const s = JSON.stringify(v);
    if (!s) return '';
    return s.length > maxLen ? s.slice(0, maxLen) + '...' : s;
  } catch (e) {
    return '';
  }
}

function errText(err) {
  const base = String(err?.message || err || 'unknown error');
  const status = getStatusCode(err);
  const body = safeJson(err?.response?.body || err?.body || err?.data || null);
  return base + (status ? (' [status ' + status + ']') : '') + (body ? (' body=' + body) : '');
}

function readStatus(json) {
  // Do not use nested result.status here; it can report completed before assets are fetchable.
  return String(
    (json &&
      (json.status ||
        json.request_status ||
        json.state ||
        json.phase ||
        (json.data && json.data.status))) ||
      ''
  ).toUpperCase();
}

function readQueuePos(json) {
  const v = json?.queue_position ?? json?.data?.queue_position ?? null;
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
}

function normalizeImages(payload) {
  const out = [];
  const seen = new Set();

  function isLikelyImageUrl(u, keyPath) {
    const s = String(u || '').trim();
    if (!/^https?:\/\//i.test(s)) return false;

    // Exclude known queue/request status endpoints that are not asset URLs.
    if (/queue\.fal\.run\/.*\/requests\//i.test(s)) return false;
    if (/\/status(?:\?|$)/i.test(s) && /fal/i.test(s)) return false;
    if (/api\.fal\.ai\/.*\/requests\//i.test(s)) return false;

    const p = String(keyPath || '').toLowerCase();
    if (/image|images|thumbnail|asset|output/.test(p)) return true;

    // Signed CDN URLs may not have extensions; allow common asset hosts/paths.
    if (/\.(png|jpe?g|webp|gif)(?:\?|#|$)/i.test(s)) return true;
    if (/fal\.(media|run)|cdn|cloudfront|storage|blob/i.test(s)) return true;

    return false;
  }

  function pushUrl(v, keyPath) {
    const u = String(v || '').trim();
    if (!u || seen.has(u)) return;
    if (!isLikelyImageUrl(u, keyPath)) return;
    seen.add(u);
    out.push({ url: u });
  }

  function consume(node, depth = 0, keyPath = '') {
    if (!node || depth > 8) return;

    if (Array.isArray(node)) {
      for (let i = 0; i < node.length; i++) consume(node[i], depth + 1, keyPath + '[' + i + ']');
      return;
    }

    if (typeof node === 'string') {
      pushUrl(node, keyPath);
      return;
    }

    if (typeof node !== 'object') return;

    for (const [k, v] of Object.entries(node)) {
      const kp = keyPath ? (keyPath + '.' + k) : k;
      if (typeof v === 'string') {
        // Prefer known image-ish keys, but recursive scan also allows signed asset URLs by host/path.
        pushUrl(v, kp);
      } else {
        consume(v, depth + 1, kp);
      }
    }
  }

  consume(payload);
  return out;
}

function buildFallbackStatusUrl(requestId) {
  return 'https://queue.fal.run/' + modelPath + '/requests/' + encodeURIComponent(requestId) + '/status';
}

function buildFallbackResultUrl(requestId) {
  return 'https://queue.fal.run/' + modelPath + '/requests/' + encodeURIComponent(requestId);
}

async function getStatusByUrl(statusUrl, requestId) {
  const url = statusUrl || buildFallbackStatusUrl(requestId);
  return await httpRequest({ method: 'GET', url, headers, json: true });
}

async function getResultByUrl(responseUrl, requestId) {
  const url = responseUrl || buildFallbackResultUrl(requestId);
  return await httpRequest({ method: 'GET', url, headers, json: true });
}

async function waitForOne(item) {
  const inputJson = item.json || {};
  const requestId = inputJson.request_id || inputJson.requestId;
  const statusUrl = String(inputJson.status_url || inputJson.statusUrl || '').trim();
  const responseUrl = String(inputJson.response_url || inputJson.responseUrl || '').trim();

  const syncImages = normalizeImages(inputJson);
  if (syncImages.length) {
    return { json: { ...inputJson, images: syncImages, falStatus: 'COMPLETED_SYNC', falPollAttempts: 0 } };
  }

  if (!requestId && !statusUrl && !responseUrl) {
    throw new Error('fal.ai submit did not return request_id/status_url/response_url.');
  }

  const startedAt = Date.now();
  let attempts = 0;
  let statusValue = '';
  let lastQueuePosition = null;

  while (attempts < maxChecks && (Date.now() - startedAt) < maxWaitMs) {
    attempts++;

    let statusJson;
    try {
      statusJson = await getStatusByUrl(statusUrl, requestId || '');
      statusValue = readStatus(statusJson);
      lastQueuePosition = readQueuePos(statusJson);
    } catch (err) {
      const code = getStatusCode(err);
      if (transientCodes.has(code)) {
        statusValue = statusValue || 'IN_QUEUE';
      } else {
        throw new Error('fal.ai status request failed for request ' + (requestId || 'unknown') + ': ' + errText(err));
      }
    }

    if (statusValue === 'COMPLETED') break;
    if (['FAILED', 'ERROR', 'CANCELLED'].includes(statusValue)) {
      throw new Error('fal.ai request ' + (requestId || 'unknown') + ' failed with status ' + statusValue + '.');
    }

    const elapsed = Date.now() - startedAt;
    const remaining = maxWaitMs - elapsed;
    if (remaining <= 0) break;
    await sleep(Math.min(pollIntervalMs, remaining));
  }

  if (statusValue !== 'COMPLETED') {
    try {
      const finalStatusJson = await getStatusByUrl(statusUrl, requestId || '');
      statusValue = readStatus(finalStatusJson) || statusValue;
      lastQueuePosition = readQueuePos(finalStatusJson) ?? lastQueuePosition;
    } catch (e) {
      // ignore
    }
  }

  let resultJson = null;
  const tryGetResult = async () => {
    for (let i = 0; i < resultRetryCount; i++) {
      try {
        const res = await getResultByUrl(responseUrl, requestId || '');
        if (res && typeof res === 'object') return res;
      } catch (err) {
        const code = getStatusCode(err);
        if (!transientCodes.has(code)) {
          throw new Error('fal.ai result request failed for request ' + (requestId || 'unknown') + ': ' + errText(err));
        }
      }
      await sleep(Math.min(1200 + i * 300, 3000));
    }
    return null;
  };

  if (statusValue === 'COMPLETED') {
    resultJson = await tryGetResult();
  } else {
    try {
      const possible = await tryGetResult();
      const hasImages = normalizeImages(possible).length > 0;
      if (hasImages) {
        resultJson = possible;
        statusValue = 'COMPLETED_LATE';
      }
    } catch (e) {
      // no-op
    }
  }

  if (!resultJson || typeof resultJson !== 'object') {
    const seconds = Math.max(1, Math.round((Date.now() - startedAt) / 1000));
    throw new Error(
      'fal.ai request ' + (requestId || 'unknown') + ' is still ' + (statusValue || 'IN_QUEUE') +
      ' after ' + attempts + ' checks (~' + seconds + 's), queue_position=' +
      (lastQueuePosition == null ? 'n/a' : lastQueuePosition) +
      '. Queue is busy or result is not ready yet. Retry /carousel in 1-2 minutes.'
    );
  }

  const normalized = normalizeImages(resultJson);
  const merged = {
    ...inputJson,
    ...resultJson,
    images: normalized,
    request_id: requestId || inputJson.request_id || '',
    falStatus: statusValue || 'COMPLETED',
    falPollAttempts: attempts,
  };

  if (!normalized.length) {
    merged.falError = 'fal.ai completed but returned no image URLs in supported fields.';
  }

  return { json: merged };
}

