function clean(s) {
  return String(s || '').replace(/[\r\n\t]+/g, ' ').replace(/\s+/g, ' ').trim();
}

function stripMeta(text) {
  let t = clean(text);
  if (!t) return t;
  t = t
    .replace(/^(why this matters now|what changed|evidence update|what this means for carers|next step|key takeaway|conclusion)\s*[:\-]\s*/i, '')
    .replace(/\b(why\s+this\s+matters\s+now|what\s+changed|evidence\s+update|key\s+takeaway|next\s+step|conclusion)\b\s*[:\-]?\s*/ig, '')
    .trim();
  return t;
}

function hashSeed(text) {
  const src = clean(text) || 'dignitate';
  let acc = 0;
  for (let i = 0; i < src.length; i++) {
    acc = (acc * 131 + src.charCodeAt(i)) % 1000000000;
  }
  return Math.abs(acc);
}

function words(text) {
  return stripMeta(text).split(/\s+/).filter(Boolean);
}

function dedupe(text) {
  let t = clean(text);
  if (!t) return t;
  for (let i = 0; i < 2; i++) {
    t = t
      .replace(/\b(\w+(?:\s+\w+){2,8})\s+\1\b/gi, '$1')
      .replace(/\b(\w+(?:\s+\w+){1,6})\s+\1\b/gi, '$1');
  }
  return clean(t);
}

function headingText(text, fallback) {
  let h = dedupe(stripMeta(text));
  if (!h) h = fallback;
  h = words(h).slice(0, 8).join(' ');
  if (words(h).length < 3) h = words(fallback).slice(0, 8).join(' ');
  return h;
}

function bodyText(text, fallback) {
  let b = dedupe(stripMeta(text));
  if (!b) b = fallback;
  const w = words(b);
  b = w.slice(0, 24).join(' ');
  if (words(b).length < 12) {
    const fw = words(fallback).slice(0, 24);
    b = fw.join(' ');
  }
  return b;
}

function cleanupRenderedBodyText(text) {
  let t = dedupe(clean(text));
  t = t
    .replace(/\bFollow Dignitate for support\.\s*for\.?/ig, 'Follow Dignitate for support.')
    .replace(/\b(Follow Dignitate(?: for support(?: and guidance[^.]*)?)?\.?)\s*\1\b/ig, '$1')
    .replace(/\bFollow Dignitate\.(?!\s*for support)/ig, 'Follow Dignitate for support.')
    .replace(/\bsupport\.\s*for\.?$/i, 'support.')
    .replace(/\bfor\.?$/i, '')
    .replace(/\bHeadline\s*:\s*/ig, '')
    .replace(/\bSubline\s*:\s*/ig, '');
  t = clean(t);
  if (t && !/[.!?]$/.test(t)) t += '.';
  return t;
}

function sanitizeSceneBrief(text) {
  return clean(text)
    .replace(/\b(NHS)\b/g, 'UK health service')
    .replace(/\b(logo|watermark|badge|brand(ed)?|poster|signage|sign\s*board|text overlay)\b/gi, 'unbranded detail')
    .replace(/\s{2,}/g, ' ');
}

function classifyTopicKind(topic) {
  const t = clean(topic).toLowerCase();
  if (!t) return 'practical';
  if (/\b(conference|summit|event|meeting|forum|congress|workshop|webinar|symposium|awards?|expo)\b/.test(t)) return 'event';
  if (/\b(medication|medications|medicine|medicines|antipsychotic|antipsychotics|prescrib(?:e|ing)|deprescrib(?:e|ing)|dose|dosing|drug|drugs|prescription)\b/.test(t)) return 'medication';
  if (/\b(research|study|trial|paper|journal|scientist|oligodendrocyte|biomarker|genetic|cell|cells|neuro|prevention\s+strateg(?:y|ies))\b/.test(t)) return 'research';
  if (/\b(framework|standard|standards|guidance|policy|government|minister|nhs\s+england|commission|rollout|strategy|plan|icb|integrated\s+care\s+board|report)\b/.test(t)) return 'policy';
  return 'practical';
}

function representationAnchor(slideIndex, role) {
  const i = Number(slideIndex || 0);
  const map = [
    'Primary subject should be a UK person of colour (South Asian or Black British), natural and realistic representation',
    'Include ethnically diverse UK people, with at least one visible person of colour in the main subjects',
    'Primary clinician or family member should be a person of colour (South Asian or Black British), realistic UK setting',
    'Primary subject should be a UK person of colour preparing notes or speaking with care team, documentary realism',
    'Closing scene should include ethnically diverse UK carers/family, with people of colour clearly represented'
  ];
  if (role === 'conclusion') return map[4];
  return map[i] || 'Use ethnically diverse UK people with people of colour represented in primary subjects';
}

function roleSceneAnchor(topicKind, role, slideIndex) {
  const i = Number(slideIndex || 0);
  if (topicKind === 'event') {
    if (i === 0) return 'conference-topic cover scene: planning desk with notebook/calendar and event registration context, no readable screen text';
    if (i === 1) return 'fact slide scene: conference venue or registration arrival moment, professional attendees, unbranded';
    if (i === 2) return 'meaning slide scene: professionals learning in session or webinar participation at desk, no readable screen UI';
    if (i === 3) return 'action slide scene: person saving date/registering at laptop with calendar and handwritten notes';
    return 'closing slide scene: supportive professional or carers conversation/group, hopeful but realistic';
  }
  if (topicKind === 'medication') {
    if (i === 0) return 'medication-topic cover scene: home medication review setup with pill packs, notebook, tea, and handwritten questions';
    if (i === 1) return 'fact slide scene: clinician and family reviewing medication list or prescription printout in calm consultation room';
    if (i === 2) return 'meaning slide scene: clinician explaining medication risks/benefits and follow-up to older patient and carer';
    if (i === 3) return 'action slide scene: person preparing for GP medication review with diary, prescription list, and notes';
    return 'closing slide scene: supportive nurse/family conversation about safer care choices, warm indoor setting';
  }
  if (topicKind === 'research') {
    if (i === 0) return 'research-topic cover scene: person reading printed research summary in home or office';
    if (i === 1) return 'fact slide scene: clinician/researcher reviewing paper or study notes with colleague';
    if (i === 2) return 'meaning slide scene: practical care-planning discussion translating evidence into care steps';
    if (i === 3) return 'action slide scene: family member preparing questions/notes before appointment, phone and diary present';
    return 'closing slide scene: supportive conversation at home or carers support setting';
  }
  if (topicKind === 'policy') {
    if (i === 0) return 'policy-topic cover scene: person reading official care update at home table';
    if (i === 1) return 'fact slide scene: professionals reviewing policy briefing in meeting room';
    if (i === 2) return 'meaning slide scene: clinician and family discussing what the update changes in practice';
    if (i === 3) return 'action slide scene: person writing next care steps in diary with phone and paperwork';
    return 'closing slide scene: community support conversation in warm indoor setting';
  }
  if (role === 'cover') return 'cover scene: carer planning at home table with notebook and calendar';
  if (role === 'conclusion') return 'closing scene: supportive family or carers moment, warm natural light';
  return 'information slide scene: UK dementia-care documentary moment, practical and unbranded';
}

function extractHeadingBody(d) {
  const h = clean(d.slideHeading || d.heading || '');
  const b = clean(d.slideBody || d.subline || '');
  if (h || b) return { heading: h, body: b };

  const t = clean(d.slideText || d.text || '');
  const idx = t.indexOf(':');
  if (idx > 0 && idx < 80) {
    return { heading: clean(t.slice(0, idx)), body: clean(t.slice(idx + 1)) };
  }

  const ws = words(t);
  return { heading: ws.slice(0, 7).join(' '), body: ws.slice(7).join(' ') };
}

return items.map((item) => {
  const d = item.json || {};

  const title = clean(d.title) || 'Dignitate Dementia Care Update';
  const topic = clean(d.args || d.title) || 'dementia care support in England';
  const topicKind = classifyTopicKind(topic);
  const slideIndex = Number(d.slideIndex || 0);
  const totalSlides = Number(d.totalSlides || 5);
  const role = String(d.slideRole || (slideIndex === 0 ? 'cover' : (slideIndex === totalSlides - 1 ? 'conclusion' : 'information'))).toLowerCase();

  const extracted = extractHeadingBody(d);

  let heading = headingText(extracted.heading, 'Dementia Care Update');
  let body = bodyText(extracted.body, 'Ask your GP for a named contact and keep one written support step for this week.');
  body = cleanupRenderedBodyText(body);

  if (role === 'conclusion' && !/\bfollow\s+dignitate\b/i.test(body)) {
    body = clean(body + ' Follow Dignitate for support.');
  }
  body = cleanupRenderedBodyText(body);

  // Keep body concise enough to avoid overflow and truncation artifacts.
  if (body.length > 165) {
    const short = body.slice(0, 165);
    const cut = short.lastIndexOf(' ');
    body = clean(cut > 0 ? short.slice(0, cut) : short);
  }
  body = cleanupRenderedBodyText(body);

  const slideImagePrompt = sanitizeSceneBrief(d.imagePrompt || d.image_prompt || d.visualPrompt || d.prompt || '');
  const sceneAnchor = roleSceneAnchor(topicKind, role, slideIndex);
  const representationRule = representationAnchor(slideIndex, role);
  const pacingAnchor = slideIndex === 0
    ? 'Slide 1 must be the most eye-catching: stronger contrast, tighter crop, one clear focal subject, and immediate emotional tension.'
    : slideIndex === 1
      ? 'Slide 2 should feel crisp and factual, with a cleaner evidence-led scene and stronger visual clarity.'
      : slideIndex === 2
        ? 'Slide 3 should deepen relevance by showing the daily-life consequence or care impact in a relatable scene.'
        : slideIndex === 3
          ? 'Slide 4 should feel practical and active, showing a visible next step the carer can imagine taking.'
          : 'Slide 5 should feel warm, reassuring, and conclusive, like an emotional payoff after the earlier slides.';

  const prompt = [
    'Create exactly ONE single 4:5 portrait photo for the background of a branded carousel slide.',
    'Dignitate style: modern, clean, UK healthcare editorial realism.',
    'Template lock: DIGNITATE_CAROUSEL_V5_VISUAL_ONLY (shared photography mood, but NO text or layout baked into the image).',
    'This output is PHOTO ONLY. A deterministic branded renderer will add the text and layout later.',
    'Image rules:',
    '- Generate only the documentary photo scene, not a full slide design.',
    '- Do NOT render any text, headline, subline, labels, dates, captions, logos, icons, UI, posters, signage, badges, or watermarks.',
    '- The image should work well when cropped into the lower visual panel of a 4:5 carousel card.',
    '- Keep one strong focal subject, clear composition, and natural editorial realism.',
    '- Keep the scene visually legible with realistic contrast and clean subject separation.',
    'Role-specific scene anchor (must follow): ' + sceneAnchor + '.',
    'Narrative pacing (must follow): ' + pacingAnchor,
    'Representation requirement (must follow): ' + representationRule + '.',
    'Photo scene brief: ' + (slideImagePrompt || 'UK dementia-care documentary moment') + '.',
    'Keep photo style consistent across the carousel: natural daylight, neutral colour palette, documentary realism, no dramatic effects.',
    'Avoid defaulting to all-white subjects; prioritise authentic UK ethnic diversity and people of colour in main subjects.',
    'If a laptop or phone appears, keep screen content unreadable or softly blurred and non-branded.',
    'Use clean backgrounds where possible; avoid waiting-room poster walls and signage-heavy scenes.',
    'Do NOT render readable brand names, posters, wall signs, or any visible organisation logo in the photo area.',
    'Topic context for scene only (NOT rendered as text): ' + topic + '.',
    'Copy context for scene only (NOT rendered as text): headline ' + heading + ' / subline ' + body + '. '
  ].join(' ');

  const falSeed = hashSeed('DIGNITATE_CAROUSEL_V4|' + title + '|' + topic + '|slide:' + slideIndex);

  return {
    json: {
      ...d,
      slideRole: role,
      slideHeading: heading,
      slideBody: body,
      falPrompt: prompt,
      falSeed,
      falPromptPreview: prompt.slice(0, 700),
    }
  };
});

const data = $input.first().json || {};
let raw = '';
try { raw = String($('Load Chat History').first().json.message || '').trim(); } catch (e) {}
if (!raw) return [{ json: data }];

const isAuto = /^\/auto(?:\b|$)/i.test(raw);
