const base = $('Parse Video Response').first().json || {};
const out = $input.first().json || {};

function looksLikeDirectImageUrl(v) {
  const u = String(v || '').trim();
  const lower = u.toLowerCase();

  if (!(lower.startsWith('http://') || lower.startsWith('https://'))) return false;
  if (lower.includes('queue.fal.run') && lower.includes('/requests/')) return false;
  if (lower.includes('/status')) return false;
  if (lower.includes('/cancel')) return false;

  if (lower.includes('fal.media/files/')) return true;

  const bare = lower.split('?')[0].split('#')[0];
  if (bare.endsWith('.png') || bare.endsWith('.jpg') || bare.endsWith('.jpeg') || bare.endsWith('.webp')) return true;

  return false;
}

function pickGeneratedPortraitUrl(payload) {
  const urls = [];
  const seen = new Set();

  function push(v) {
    const u = String(v || '').trim();
    if (!u || seen.has(u) || !looksLikeDirectImageUrl(u)) return;
    seen.add(u);
    urls.push(u);
  }

  function walk(node, depth = 0) {
    if (node == null || depth > 7) return;

    if (Array.isArray(node)) {
      for (const x of node) walk(x, depth + 1);
      return;
    }

    if (typeof node === 'string') {
      push(node);
      return;
    }

    if (typeof node !== 'object') return;

    push(node.image_url);
    push(node.imageUrl);
    push(node.url);

    walk(node.images, depth + 1);
    walk(node.output, depth + 1);
    walk(node.result, depth + 1);
    walk(node.data, depth + 1);
    walk(node.response, depth + 1);

    for (const v of Object.values(node)) {
      if (v && typeof v === 'object') walk(v, depth + 1);
    }
  }

  walk(payload);
  return urls[0] || '';
}

const generatedPortraitUrl = pickGeneratedPortraitUrl(out);
const originalCreatorUrl = String(base.creatorImageUrl || '').trim();

// Keep original founder profile image as the identity anchor for clip generation.
const clipIdentityImageUrl = originalCreatorUrl || generatedPortraitUrl;

const founderPortraitSource = originalCreatorUrl
  ? 'profile_locked'
  : (generatedPortraitUrl ? 'generated_only' : 'none');

return [{
  json: {
    ...base,
    creatorImageUrl: clipIdentityImageUrl,
    // Preserve the founder portrait pool for downstream scene generation.
    creatorImageUrls: Array.isArray(out.creatorImageUrls) && out.creatorImageUrls.length
      ? out.creatorImageUrls
      : (Array.isArray(base.creatorImageUrls) ? base.creatorImageUrls : []),
    generatedFounderPortraitUrl: generatedPortraitUrl,
    founderPortraitSource
  }
}];

const data = $input.first().json || {};
const qid = String(data.callbackQueryId || '').trim();
if (!qid) return [];
return [{ json: { callbackQueryId: qid } }];

const src = ($json.body && typeof $json.body === 'object') ? $json.body : ($json || {});
const chatId = String(src.chatId || '').trim();
if (!chatId) return [];

// Idempotency guard
const _cbKey = String(src.renderJobId || src.callbackId || src.jobId || src.requestId || '').trim();
if (_cbKey) {
  if (!staticData.processedCallbacks) staticData.processedCallbacks = {};
  const _now = Date.now();
  // Prune entries older than 1 hour to prevent unbounded growth
  for (const k of Object.keys(staticData.processedCallbacks)) {
    if (_now - staticData.processedCallbacks[k] > 3600000) delete staticData.processedCallbacks[k];
  }
  if (staticData.processedCallbacks[_cbKey]) return []; // duplicate — drop
  staticData.processedCallbacks[_cbKey] = _now;
}

function clean(s) {
  return String(s || '').replace(/[\r\n]+/g, ' ').replace(/\s+/g, ' ').trim();
}

function uniqHashtags(list) {
  const out = [];
  const seen = new Set();
  for (const raw of (Array.isArray(list) ? list : [])) {
    let h = clean(raw);
    if (!h) continue;
    if (!h.startsWith('#')) h = '#' + h;
    const key = h.toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    out.push(h);
  }
  return out;
}

const localPublicMatchers = [
  /^https?:\/\/187\.77\.178\.148:3001\/public\/(.+)$/i,
  /^https?:\/\/srv1417199\.hstgr\.cloud\/public\/(.+)$/i,
];

function normalizeAssetUrl(raw) {
  return String(raw || '').trim();
}

function toDownloadUrl(raw) {
  const u = normalizeAssetUrl(raw);
  if (!u) return '';
  for (const re of localPublicMatchers) {
    const match = u.match(re);
    if (match && match[1]) {
      return 'http://187.77.178.148:3001/public/' + match[1];
    }
  }
  return u;
}

const statusRaw = String(src.status || '').trim();
const status = statusRaw ? statusRaw.toLowerCase() : '';
const assetType = String(src.assetType || 'video').trim().toLowerCase();
const title = String(src.title || 'Untitled Content').trim();
const publicVideoUrl = normalizeAssetUrl(src.videoUrl || '');
const publicVideoUrls = Array.isArray(src.videoUrls)
  ? src.videoUrls.map((u) => normalizeAssetUrl(u)).filter(Boolean)
  : (publicVideoUrl ? [publicVideoUrl] : []);
const downloadVideoUrl = toDownloadUrl(publicVideoUrl);
const downloadVideoUrls = publicVideoUrls.map((u) => toDownloadUrl(u)).filter(Boolean);
const videoTitles = Array.isArray(src.videoTitles)
  ? src.videoTitles.map((value) => clean(value)).filter(Boolean)
  : [];
const videoDescriptions = Array.isArray(src.videoDescriptions)
  ? src.videoDescriptions.map((value) => clean(value)).filter(Boolean)
  : [];
const imageUrls = Array.isArray(src.allImageUrls)
  ? src.allImageUrls.map((u) => normalizeAssetUrl(u)).filter(Boolean)
  : [];
const downloadImageUrls = imageUrls.map((u) => toDownloadUrl(u)).filter(Boolean);

const staticData = $getWorkflowStaticData('global');
if (!staticData.pendingContent) staticData.pendingContent = {};
if (!Array.isArray(staticData.approvedArchiveQueue)) staticData.approvedArchiveQueue = [];
if (staticData.activeGenerationByChat?.[chatId]) delete staticData.activeGenerationByChat[chatId];

const pending = staticData.pendingContent[chatId] && typeof staticData.pendingContent[chatId] === 'object'
  ? staticData.pendingContent[chatId]
  : null;
const pendingTitle = String(pending?.title || '').trim();
const pendingType = String(pending?.type || '').trim().toLowerCase();
const pendingMatchesTitle = pending && pendingType === assetType && pendingTitle && pendingTitle.toLowerCase() === title.toLowerCase();

const pendingCaption = pendingMatchesTitle ? String(pending?.caption || '').trim() : String(src.caption || '').trim();
const pendingHashtags = pendingMatchesTitle && Array.isArray(pending?.hashtags) ? pending.hashtags : (Array.isArray(src.hashtags) ? src.hashtags : []);
const pendingSlides = Array.isArray(pending?.slides) ? pending.slides : [];
const pendingArgs = String(pending?.args || '').trim();
const pendingBackgrounds = Array.isArray(pending?.backgroundImageUrls)
  ? pending.backgroundImageUrls.map((u) => normalizeAssetUrl(u)).filter(Boolean)
  : [];
const pendingDownloadImageUrls = Array.isArray(pending?.downloadImageUrls)
  ? pending.downloadImageUrls.map((u) => normalizeAssetUrl(u)).filter(Boolean)
  : [];

if (assetType === 'carousel') {
  const finalImageUrls = imageUrls.length ? imageUrls : pendingBackgrounds;
  const finalDownloadImageUrls = downloadImageUrls.length
    ? downloadImageUrls
    : (pendingDownloadImageUrls.length ? pendingDownloadImageUrls : finalImageUrls.map((u) => toDownloadUrl(u)).filter(Boolean));
  const carouselOk = status === 'success' && finalImageUrls.length > 0;

  if (!carouselOk) {
    const err = String(src.error || 'Unknown carousel render error').slice(0, 700);
    return [{
      json: {
        chatId,
        title,
        callbackKind: 'carousel',
        status: status || 'error',
        renderOk: false,
        text: ['Carousel render failed.', '', 'Title: ' + title, 'Error: ' + err].join('\n')
      }
    }];
  }

  const finalSlides = Array.isArray(src.slides) && src.slides.length ? src.slides : pendingSlides;
  const finalCaption = String(src.caption || pendingCaption).trim();
  const finalHashtags = uniqHashtags(Array.isArray(src.hashtags) ? src.hashtags : pendingHashtags).slice(0, 12);
  const finalArgs = String(src.args || pendingArgs).trim();

  staticData.pendingContent[chatId] = {
    type: 'carousel',
    title,
    slides: finalSlides,
    hashtags: finalHashtags,
    caption: finalCaption,
    backgroundImageUrls: finalImageUrls,
    downloadImageUrls: finalDownloadImageUrls,
    allImageUrls: finalImageUrls,
    imageUrl: finalImageUrls[0] || '',
    firstImageUrl: finalImageUrls[0] || '',
    imageCount: finalImageUrls.length,
    chatId,
    args: finalArgs,
    renderStatus: 'success',
    renderPending: false,
    timestamp: Date.now()
  };

  return [{
    json: {
      callbackKind: 'carousel',
      status: 'success',
      renderOk: true,
      chatId,
      title,
      slides: finalSlides,
      hashtags: finalHashtags,
      caption: finalCaption,
      args: finalArgs,
      backgroundImageUrls: finalImageUrls,
      downloadImageUrls: finalDownloadImageUrls,
      allImageUrls: finalImageUrls,
      imageUrl: finalImageUrls[0] || '',
      firstImageUrl: finalImageUrls[0] || '',
      imageCount: finalImageUrls.length,
      text: ['Carousel render complete.', '', 'Title: ' + title, '', 'Slides ready: ' + finalImageUrls.length, '', 'Asset host: VPS'].join('\n')
    }
  }];
}

const renderOk = status === 'success' && publicVideoUrls.length > 0;
const hashtags = uniqHashtags(Array.isArray(src.hashtags) ? src.hashtags : pendingHashtags).slice(0, 12);

if (renderOk && assetType !== 'meeting_reels') {
  const baseType = 'video';
  const base = pendingMatchesTitle && pending && pending.type === baseType
    ? { ...pending }
    : { type: baseType, chatId, title, caption: '', hashtags: [], timestamp: Date.now() };

  staticData.pendingContent[chatId] = {
    ...base,
    title,
    finalVideoUrl: publicVideoUrl,
    videoUrl: publicVideoUrl,
    videoUrls: publicVideoUrls,
    renderStatus: 'success',
    renderedAt: Date.now(),
  };
}

if (renderOk && assetType === 'meeting_reels') {
  const createdAt = Date.now();
  const baseTitle = String(pending?.title || title || 'Meeting Highlights').trim();
  const baseCaption = String(src.caption || pendingCaption || 'Meeting highlight reel ready for review.').trim();
  const baseHashtags = hashtags.length ? hashtags : ['#Dignitate', '#MeetingReels'];
  const existingItems = Array.isArray(pending?.approvalItems) ? pending.approvalItems : [];
  const existingByUrl = new Map(
    existingItems
      .map((item) => [normalizeAssetUrl(item?.videoUrl || item?.finalVideoUrl || ''), item])
      .filter(([u]) => Boolean(u))
  );

  function shortHash(...parts) {
    const raw = parts.map((part) => String(part || '')).join('|');
    let hash = 0;
    for (let i = 0; i < raw.length; i++) {
      hash = ((hash << 5) - hash) + raw.charCodeAt(i);
      hash |= 0;
    }
    return Math.abs(hash).toString(36);
  }

  const approvalItems = publicVideoUrls.map((u, idx) => {
    const reelNumber = idx + 1;
    const reelTitle = videoTitles[idx] || `${baseTitle} - Reel ${reelNumber}`;
    const reelDescription = videoDescriptions[idx] || '';
    const existing = existingByUrl.get(u) || {};
    return {
      type: 'video',
      assetType: 'video',
      chatId,
      title: reelTitle,
      parentTitle: baseTitle,
      caption: reelDescription || baseCaption,
      description: reelDescription,
      hashtags: baseHashtags,
      videoUrl: u,
      finalVideoUrl: u,
      downloadVideoUrl: downloadVideoUrls[idx] || toDownloadUrl(u),
      approvalId: String(existing.approvalId || `meeting-${shortHash(chatId, baseTitle, reelTitle, u, reelNumber)}`),
      archiveId: String(existing.archiveId || `archive-${shortHash(chatId, baseTitle, reelTitle, u, 'approved')}`),
      sourceVideoUrl: String(src.sourceVideoUrl || pending?.sourceVideoUrl || pendingArgs || '').trim(),
      meetingConfig: (pending?.meetingConfig && typeof pending.meetingConfig === 'object') ? pending.meetingConfig : {},
      args: pendingArgs,
      timestamp: createdAt,
    };
  });

  staticData.pendingContent[chatId] = {
    ...(pending && pending.type === 'meeting_reels' ? pending : {}),
    type: 'meeting_reels',
    title: baseTitle,
    caption: baseCaption,
    hashtags: baseHashtags,
    chatId,
    args: pendingArgs,
    sourceVideoUrl: String(src.sourceVideoUrl || pending?.sourceVideoUrl || pendingArgs || '').trim(),
    meetingConfig: (pending?.meetingConfig && typeof pending.meetingConfig === 'object') ? pending.meetingConfig : {},
    finalVideoUrl: publicVideoUrl || publicVideoUrls[0] || '',
    videoUrl: publicVideoUrl || publicVideoUrls[0] || '',
    videoUrls: publicVideoUrls,
    approvalItems,
    renderStatus: 'success',
    renderPending: false,
    renderedAt: createdAt,
    timestamp: pending?.timestamp || createdAt,
  };

  return approvalItems.map((item, idx) => {
    const reelNumber = idx + 1;
    const reelCaption = [
      `MEETING REEL ${reelNumber}/${approvalItems.length}`,
      '',
      'Title: ' + item.title,
      ...(item.description ? ['', 'Description: ' + item.description] : []),
      ...(item.hashtags?.length ? ['', 'Hashtags: ' + item.hashtags.join(' ')] : []),
      '',
      'Asset host: VPS',
      '',
      'Tap Approve to send this reel into the posting flow.'
    ].join('\n');

    return {
      json: {
        callbackKind: 'video',
        chatId,
        title: item.title,
        parentTitle: item.parentTitle,
        status: 'success',
        assetType,
        videoUrl: item.videoUrl,
        videoUrls: publicVideoUrls,
        downloadVideoUrl: item.downloadVideoUrl,
        downloadVideoUrls,
        renderOk: true,
        approvalId: item.approvalId,
        archiveId: item.archiveId,
        caption: item.caption,
        description: item.description,
        hashtags: item.hashtags,
        approvalCaption: reelCaption,
        text: ['Meeting reel ready.', '', 'Title: ' + item.title, ...(item.description ? ['', item.description] : []), '', `Reel ${reelNumber}/${approvalItems.length}`, item.videoUrl].join('\n')
      }
    };
  });
}

let approvalCaption = '';
if (renderOk) {
  const parts = [
    assetType === 'meeting_reels' ? 'MEETING REELS READY FOR REVIEW' : 'VIDEO READY FOR REVIEW',
    '',
    'Title: ' + title,
  ];

  if (assetType === 'meeting_reels') {
    parts.push('', 'Reels: ' + publicVideoUrls.length);
  }

  if (pendingCaption) {
    parts.push('', 'Draft caption:', pendingCaption);
  }

  if (hashtags.length) {
    parts.push('', 'Hashtags: ' + hashtags.join(' '));
  }

  parts.push('', 'Asset host: VPS');
  parts.push('', 'Tap a button below: Approve to post, or Regenerate for a new version.');

  const joined = parts.join('\n');
  approvalCaption = joined.length > 1000 ? (joined.slice(0, 997).trim() + '...') : joined;
}

let text = '';
if (renderOk) {
  text = assetType === 'meeting_reels'
    ? ['Meeting reels render complete.', '', 'Title: ' + title, '', ...publicVideoUrls].join('\n')
    : ['Video render complete.', '', 'Title: ' + title, '', publicVideoUrl].join('\n');
}

if (!renderOk) {
  const err = String(src.error || 'Unknown render error').slice(0, 700);
  text = ['Video render failed.', '', 'Title: ' + title, 'Error: ' + err].join('\n');
}

return [{
  json: {
    callbackKind: 'video',
    chatId,
    title,
    status: renderOk ? 'success' : (status || 'error'),
    assetType,
    videoUrl: publicVideoUrl,
    videoUrls: publicVideoUrls,
    downloadVideoUrl,
    downloadVideoUrls,
    renderOk,
    approvalCaption,
    text,
  }
}];

function clean(s) {
  return String(s || '').replace(/[\r\n]+/g, ' ').replace(/\s+/g, ' ').trim();
}

function uniqHashtags(list) {
  const out = [];
  const seen = new Set();
  for (const raw of (Array.isArray(list) ? list : [])) {
    let h = clean(raw);
    if (!h) continue;
    if (!h.startsWith('#')) h = '#' + h;
    const k = h.toLowerCase();
    if (seen.has(k)) continue;
    seen.add(k);
    out.push(h);
  }
  return out;
}

function normalizeGithubRawUrl(u) {
  const s = clean(u);
  const m = s.match(/^https?:\/\/github\.com\/([^\/]+)\/([^\/]+)\/blob\/([^\/]+)\/(.+)$/i);
  if (m) return `https://raw.githubusercontent.com/${m[1]}/${m[2]}/${m[3]}/${m[4]}`;
  return s;
}

function normalizeUrlList(list) {
  const out = [];
  const seen = new Set();
  for (const raw of (Array.isArray(list) ? list : [])) {
    const u = normalizeGithubRawUrl(raw);
    if (!/^https?:\/\//i.test(u)) continue;
    const key = u.toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    out.push(u);
  }
  return out;
}

const j = $input.first().json || {};
if (j.error) return [{ json: j }];

const staticData = $getWorkflowStaticData('global');
if (!staticData.creatorProfileByChat) staticData.creatorProfileByChat = {};

const chatId = j.chatId;
const title = clean(j.title || j.args || 'Dignitate Video');
const caption = clean(j.caption || 'Research-backed guidance for carers with clear next steps.');
const hashtags = uniqHashtags(j.hashtags || []).slice(0, 12);

const videoUrl = clean(j.finalVideoUrl || j.videoUrl || '');
if (!videoUrl) {
  return [{
    json: {
      chatId,
      error: true,
      message: 'Video is not rendered yet (no MP4 URL found). Please wait for the render to finish, then approve again.'
    }
  }];
}

const creatorDefaults = normalizeUrlList([
  'https://srv1417199.hstgr.cloud/public/founders/malcolm-20260320-portrait-01.jpeg',
  'https://srv1417199.hstgr.cloud/public/founders/malcolm-20260320-portrait-02.jpeg',
  'https://raw.githubusercontent.com/dignitatesocial/dignitatevideo/main/malcolm_portrait_casual.png',
  'https://raw.githubusercontent.com/dignitatesocial/dignitatevideo/main/malcolm_portrait_suit.png'
]);

const profile = staticData.creatorProfileByChat[String(chatId || '')] || staticData.creatorProfileByChat[String(staticData.defaultChatId || '')] || {};
const profilePool = normalizeUrlList(profile.faceUrls || []);
const incomingPool = normalizeUrlList(j.creatorImageUrls || []);
const preferredCoverImageUrl = clean(
  j.coverImageUrl ||
  j.generatedFounderPortraitUrl ||
  j.creatorImageUrl ||
  profile.faceUrl ||
  incomingPool[0] ||
  profilePool[0] ||
  creatorDefaults[0] ||
  ''
);

let generatedCoverUrl = clean(j.coverImageUrl || '');
if (!generatedCoverUrl && preferredCoverImageUrl) {
  const coverLabel = j.sourceVideoUrl ? 'MEETING REEL' : 'DIGNITATE REEL';
  try {
    const coverResp = await this.helpers.httpRequest({
      method: 'POST',
      url: 'http://187.77.178.148:3001/cover/founder-reel',
      body: {
        imageUrl: preferredCoverImageUrl,
        title,
        label: coverLabel,
      },
      json: true,
    });
    generatedCoverUrl = clean(coverResp?.coverUrl || '');
  } catch (error) {
    generatedCoverUrl = '';
  }
}

const igCaption = [title, caption, hashtags.join(' ')].filter(Boolean).join('\n\n').slice(0, 2100);
const facebookCaption = [title, caption, hashtags.slice(0, 8).join(' ')].filter(Boolean).join('\n\n').slice(0, 4900);

const ytTitleBase = title.length > 90 ? title.slice(0, 87).trim() + '...' : title;
const ytTitle = (ytTitleBase + ' #Shorts').slice(0, 100);
const ytDescription = [caption, '', hashtags.join(' '), '#Shorts'].filter(Boolean).join('\n').slice(0, 4500);

const ttCaption = (caption + (hashtags.length ? (' ' + hashtags.slice(0, 8).join(' ')) : '')).slice(0, 2000);

const uuidRe = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

const rawTikTokId = '';
const rawYouTubeId = 'ac_45guMz9S841I';
const rawFacebookPageId = clean(j.facebookPageId || '672136448');

const tiktokConnectedAccountUuid = uuidRe.test(rawTikTokId) ? rawTikTokId : '';
const youtubeConnectedAccountUuid = uuidRe.test(rawYouTubeId) ? rawYouTubeId : '';

const tiktokEntityId = (!tiktokConnectedAccountUuid && rawTikTokId) ? rawTikTokId : '';
const youtubeEntityId = (!youtubeConnectedAccountUuid && rawYouTubeId) ? rawYouTubeId : '';

return [{
  json: {
    ...j,
    type: 'video',
    chatId,
    title,
    caption,
    hashtags,
    videoUrl,
    instagramCaption: igCaption,
    instagramCoverUrl: generatedCoverUrl,
    coverImageUrl: generatedCoverUrl,
    coverSourceImageUrl: preferredCoverImageUrl,
    facebookCaption,
    facebookPageId: rawFacebookPageId,
    youtubeTitle: ytTitle,
    youtubeDescription: ytDescription,
    youtubeThumbnailUrl: generatedCoverUrl,
    tiktokCaption: ttCaption,
    tiktokConnectedAccountUuid,
    youtubeConnectedAccountUuid,
    tiktokEntityId,
    youtubeEntityId,
    connectedAccountValidation: {
      rawTikTokId,
      rawYouTubeId,
      rawFacebookPageId,
      tiktokValidUuid: Boolean(tiktokConnectedAccountUuid),
      youtubeValidUuid: Boolean(youtubeConnectedAccountUuid),
      tiktokHasEntityId: Boolean(tiktokEntityId),
      youtubeHasEntityId: Boolean(youtubeEntityId),
      facebookConfigured: Boolean(rawFacebookPageId)
    }
  }
}];

// Store most recent video post metadata for /stats
const staticData = $getWorkflowStaticData('global');
if (!staticData.recentPosts) staticData.recentPosts = [];
try {
  const igRaw = $('Composio - Instagram Reels').first().json;
  const igMediaId = igRaw?.data?.id || igRaw?.id || null;
  const postTitle = $('Prepare Video Post Data').first().json?.title || 'Video';
  if (igMediaId) {
    staticData.recentPosts.unshift({
      type: 'video', title: postTitle,
      timestamp: Date.now(), igMediaId,
      platforms: ['Instagram Reels', 'Facebook Video', 'TikTok', 'YouTube Shorts']
    });
    staticData.recentPosts = staticData.recentPosts.slice(0, 10);
  }
} catch(e) {}

const base = $('Prepare Video Post Data').first().json || {};
const chatId = base.chatId;

function statusFrom(nodeName) {
  try {
    const j = $(nodeName).first().json || {};
    if (j.error) return { status: 'Failed', detail: String(j.error?.message || j.message || j.error || '').slice(0, 200) };
    if (j.successful === false || j.successfull === false) return { status: 'Failed', detail: String(j.message || '').slice(0, 200) };
    if (j.status && Number(j.status) >= 400) return { status: 'Failed', detail: String(j.message || '').slice(0, 200) };
    return { status: 'Posted', detail: '' };
  } catch (e) {
    return { status: 'Skipped', detail: 'Not configured or not executed.' };
  }
}

const val = base.connectedAccountValidation || {};
const ttNote = (!val.tiktokValidUuid && val.rawTikTokId && val.rawTikTokId.startsWith('ac_'))
  ? ' (using entityId mode with ac_...; if this fails, Composio may require a UUID connected account id)'
  : (!val.tiktokValidUuid && val.rawTikTokId ? ' (invalid TikTok id)' : '');
const ytNote = (!val.youtubeValidUuid && val.rawYouTubeId && val.rawYouTubeId.startsWith('ac_'))
  ? ' (using entityId mode with ac_...; if this fails, Composio may require a UUID connected account id)'
  : (!val.youtubeValidUuid && val.rawYouTubeId ? ' (invalid YouTube id)' : '');

const ig = statusFrom('Composio - Instagram Reels');
const fb = base.facebookPageId
  ? statusFrom('Composio - Facebook Video')
  : { status: 'Skipped', detail: 'Facebook Page ID not set' };
const tt = (base.tiktokConnectedAccountUuid || base.tiktokEntityId)
  ? statusFrom('Composio - TikTok')
  : { status: 'Skipped', detail: 'TikTok account not set' };
const yt = (base.youtubeConnectedAccountUuid || base.youtubeEntityId)
  ? statusFrom('Composio - YouTube Shorts')
  : { status: 'Skipped', detail: 'YouTube account not set' };

const lines = [
  'VIDEO POST RESULTS',
  '',
  `Instagram Reels: ${ig.status}${ig.detail ? ` (${ig.detail})` : ''}`,
  `Facebook Video: ${fb.status}${fb.detail ? ` (${fb.detail})` : ''}`,
  `TikTok: ${tt.status}${ttNote}${tt.detail ? ` (${tt.detail})` : ''}`,
  `YouTube Shorts: ${yt.status}${ytNote}${yt.detail ? ` (${yt.detail})` : ''}`,
  '',
  `Title: ${base.title || ''}`,
  base.videoUrl ? `MP4: ${base.videoUrl}` : ''
].filter(Boolean);

return [{ json: { chatId, message: lines.join('\n') } }];

const base = $('Prepare Video Post Data').first().json || {};
const resp = $input.first().json;

// Response shapes: {items:[...]} or {data:[...]} or [...].
let items = [];
if (Array.isArray(resp)) items = resp;
else if (Array.isArray(resp?.items)) items = resp.items;
else if (Array.isArray(resp?.data)) items = resp.data;
else if (Array.isArray(resp?.connected_accounts)) items = resp.connected_accounts;

const uuidRe = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
let found = '';
for (const it of items) {
  const id = String(it?.id || it?.connectedAccountId || it?.connected_account_id || '').trim();
  if (uuidRe.test(id)) { found = id; break; }
}

// If v3 returns nothing, keep whatever we already had.
const merged = { ...base };
if (found && !merged.youtubeConnectedAccountUuid) {
  merged.youtubeConnectedAccountUuid = found;
}

return [{ json: merged }];

// ElevenLabs HTTP Request (responseFormat=file) can drop upstream JSON fields.
// Reattach the real video payload so downstream nodes always have creatorImageUrl(s), args, title, etc.
const base = $('Restore Video Payload').first().json || {};
const current = $input.first();

return [{
  json: {
    ...base,
    ...(current?.json || {})
  },
  binary: current?.binary
}];

