// OpenClaw -> Telegram-shaped update adapter (hardcoded integration values)
const EXPECTED_SECRET = 'my_secure_secret_12345';
const FIELD_CHAT_ID = 'chatId';
const FIELD_TEXT = 'text';
const FIELD_CALLBACK_DATA = 'callbackData';
const FIELD_USER_ID = 'userId';
const FIELD_MESSAGE_ID = 'messageId';

const raw = $input.first().json || {};
const headers = raw.headers || raw.header || {};
const body = (raw.body && typeof raw.body === 'object' && !Array.isArray(raw.body)) ? raw.body : raw;
const query = raw.query || {};

function pickHeader(obj, keys) {
  const src = obj && typeof obj === 'object' ? obj : {};
  for (const k of keys) {
    const exact = src[k];
    if (exact != null && String(exact).trim()) return String(exact).trim();
    const foundKey = Object.keys(src).find((x) => String(x).toLowerCase() === String(k).toLowerCase());
    if (foundKey && src[foundKey] != null && String(src[foundKey]).trim()) return String(src[foundKey]).trim();
  }
  return '';
}

function clean(s) {
  return String(s == null ? '' : s).trim();
}

function toNumOrString(v, fallback = null) {
  if (v == null || v === '') return fallback;
  const n = Number(v);
  return Number.isFinite(n) ? n : String(v);
}

function normalizePlatformScopedId(v) {
  const raw = clean(v);
  if (!raw) return '';
  const stripped = raw.replace(/^telegrams*:/i, '').trim();
  return stripped || raw;
}

const providedSecret = pickHeader(headers, ['x-openclaw-secret', 'x-openclaw-signature']) || clean(query.secret);
if (EXPECTED_SECRET && providedSecret !== EXPECTED_SECRET) {
  throw new Error('Unauthorized OpenClaw webhook request (missing or invalid X-OpenClaw-Secret)');
}

const chatIdRaw = normalizePlatformScopedId(body[FIELD_CHAT_ID] ?? body.chat_id ?? body.chat);
const userIdRaw = normalizePlatformScopedId(body[FIELD_USER_ID] ?? body.user_id ?? body.fromId);
const text = clean(body[FIELD_TEXT]);
const callbackData = clean(body[FIELD_CALLBACK_DATA]);
const messageIdRaw = body[FIELD_MESSAGE_ID] ?? body.message_id ?? body.updateMessageId;
const sourceMessageIdRaw = body.sourceMessageId ?? body.source_message_id ?? messageIdRaw;
const sourceMessageText = clean(body.sourceMessageText || body.source_message_text || body.originalMessageText || '');
const callbackQueryId = clean(body.callbackQueryId || body.callback_query_id || body.requestId || '');
const requestId = clean(body.requestId || body.request_id || '');

const chatId = toNumOrString(chatIdRaw, null);
const userId = toNumOrString(userIdRaw, chatId);
const messageId = toNumOrString(messageIdRaw, Date.now());
const sourceMessageId = toNumOrString(sourceMessageIdRaw, messageId);

if (chatId == null) {
  throw new Error('OpenClaw payload missing chatId');
}

const nowSec = Math.floor(Date.now() / 1000);

let update;
if (callbackData) {
  update = {
    update_id: nowSec,
    callback_query: {
      id: callbackQueryId || requestId || String(Date.now()),
      from: { id: userId == null ? chatId : userId, is_bot: false },
      data: callbackData,
      message: {
        message_id: sourceMessageId,
        date: nowSec,
        chat: { id: chatId, type: 'private' },
        text: sourceMessageText || text || ''
      }
    }
  };
} else {
  update = {
    update_id: nowSec,
    message: {
      message_id: messageId,
      date: nowSec,
      chat: { id: chatId, type: 'private' },
      from: { id: userId == null ? chatId : userId, is_bot: false },
      text: text || ''
    }
  };
}

return [{
  json: {
    ...update,
    openclaw: {
      source: 'openclaw',
      responseMode: 'sync',
      botMode: 'openclaw_owns_telegram',
      webhookPath: 'http://187.77.178.148:5678/webhook/openclaw',
      requestId,
      rawPayload: body
    }
  }
}];

const data = $input.first().json || {};
const backgroundImageUrls = Array.isArray(data.backgroundImageUrls)
  ? data.backgroundImageUrls.filter(Boolean)
  : (Array.isArray(data.allImageUrls) ? data.allImageUrls.filter(Boolean) : []);
if (!backgroundImageUrls.length) {
  throw new Error('No background image URLs found for branded carousel render dispatch.');
}
return [{
  json: {
    ...data,
    backgroundImageUrls,
    renderPending: true
  }
}];

